window.KMAP_EXTRA.taiwan = {"TW-CHA":[{"k":"origin","zh":"清代舊稱「半線」，1723年設縣時由雍正帝賜予現名","en":"Once called Poann-soann (Banxian); its current name was granted by the Yongzheng Emperor in 1723.","ja":"旧名は「半線」。1723年の県設置時に雍正帝が現名を与えた"},{"k":"symbol","zh":"縣鳥是灰面鷲，縣花是菊花","en":"Its county bird is the grey-faced buzzard; its flower is the chrysanthemum.","ja":"県の鳥はサシバ（灰面鷲）、県の花はキク"},{"k":"record","zh":"1719年完工的八堡圳，是臺灣最早開鑿的水圳","en":"The Babao Canal, finished in 1719, was the first irrigation canal dug in Taiwan.","ja":"1719年完成の八堡圳は、台湾で最初に掘られた用水路"},{"k":"festival","zh":"二水每年舉辦「跑水節」，紀念指點開圳卻不留名、只自稱「林先生」的老翁","en":"Ershui's Water Running Festival honors \"Mr. Lin\", a nameless old man said to have shown how to dig the canal.","ja":"二水の「跑水節」は、用水路の掘り方を教え名を告げなかった「林先生」を記念する"},{"k":"work","zh":"電影《那些年，我們一起追的女孩》大多在這裡拍攝，片中學校是九把刀的母校","en":"Most of the film You Are the Apple of My Eye was shot here; its school is director Giddens Ko's alma mater.","ja":"映画『あの頃、君を追いかけた』の大半はここで撮影。劇中の学校は監督・九把刀の母校"},{"k":"sport","zh":"「臺灣米倉田中馬拉松」被稱為臺灣四大馬拉松之一","en":"The Tianzhong \"Rice Granary\" Marathon is called one of Taiwan's four great marathons.","ja":"「台湾米倉田中マラソン」は台湾四大マラソンの一つとされる"},{"k":"record","zh":"臺灣本島平均海拔最低的縣","en":"It has the lowest average elevation of any county on Taiwan's main island.","ja":"台湾本島で平均標高が最も低い県"},{"k":"life","zh":"本島唯一沒有任何鄉鎮面積超過100平方公里的縣","en":"The only county on the main island where no township exceeds 100 km².","ja":"どの郷鎮も100km²を超えない、本島で唯一の県"},{"k":"history","zh":"1895年乙未戰爭最大的正面會戰在八卦山爆發，義軍最後失守","en":"The largest pitched battle of the 1895 war against Japan's invasion was fought on Baguashan here.","ja":"1895年の乙未戦争で最大の正面会戦が八卦山で起こり、義勇軍は敗れた"},{"k":"history","zh":"1784年鹿港與泉州蚶江正式設口對渡，開啟港口的全盛期","en":"In 1784 Lukang opened an official ferry link with Quanzhou's Hanjiang, starting its golden age.","ja":"1784年に鹿港と泉州の蚶江を結ぶ正式な航路が開かれ、港の最盛期が始まった"},{"k":"history","zh":"1850年鹿港因泥沙淤塞、船隻進不來，商港地位漸被淡水取代","en":"By 1850 silt had choked Lukang's harbor, and its trade gradually shifted to Tamsui.","ja":"1850年頃に鹿港は土砂で埋まり、交易の座は次第に淡水へ移った"},{"k":"origin","zh":"鹿港最早見於1696年的《台灣府志》，當時寫作「鹿仔港」","en":"Lukang first appears in the 1696 Taiwan Prefecture gazetteer under the name 'Lu-a Harbor'.","ja":"鹿港は1696年の『台湾府志』に「鹿仔港」として初めて登場する"},{"k":"origin","zh":"二水舊稱「二八水」，一說源自把約兩成水量分給另一條圳的分水圳","en":"Ershui was once 'Erbashui', possibly from a canal that diverted about 20% of its water to another.","ja":"二水の旧称は「二八水」。水の約2割を別の水路に分けた分水路に由来する説がある"},{"k":"origin","zh":"和美的名字據說寓意漳州人與泉州人「和睦相處、創建美好地方」","en":"Hemei's name reportedly expresses Zhangzhou and Quanzhou settlers living in harmony to build a good place.","ja":"和美の名は、漳州人と泉州人が仲良く暮らし美しい地を築くという願いに由来するという"},{"k":"brand","zh":"鹿港頂番里被稱為全世界最大的水龍頭等水五金產地","en":"Dingfan in Lukang is called the world's largest production center for faucets and plumbing hardware.","ja":"鹿港の頂番里は、蛇口など水回り金具の世界最大の産地とされる"},{"k":"brand","zh":"1970至80年代臺灣約一半的雨傘產自和美","en":"In the 1970s–80s about half of Taiwan's umbrellas were made in Hemei.","ja":"1970〜80年代、台湾の傘の約半分が和美で作られていた"},{"k":"brand","zh":"泰山企業與維力食品，都是從田中發跡的","en":"Food companies Taisun Enterprise and Wei Lih Food both got their start in Tianzhong here.","ja":"泰山企業と維力食品は、どちらも田中から発展した企業"},{"k":"brand","zh":"自行車大廠美利達，1972年由曾鼎煌在員林創立","en":"Bicycle maker Merida was founded in Yuanlin in 1972 by Ike Tseng.","ja":"自転車メーカーのメリダは、1972年に曾鼎煌が員林で創業した"},{"k":"brand","zh":"二水用濁水溪溪石雕成的螺溪石硯遠近馳名","en":"Ershui's Luoxi inkstones are carved from stones taken from the Zhuoshui River.","ja":"二水の螺渓石硯は、濁水渓の川石から彫られる名品"},{"k":"symbol","zh":"二水在2005年建起臺灣第一座以臺灣獼猴為主題的生態教育園區","en":"Ershui opened Taiwan's first eco-education park devoted to Formosan macaques in 2005.","ja":"二水には2005年、台湾初のタイワンザルをテーマにした生態教育園区ができた"},{"k":"work","zh":"羅大佑的歌曲〈鹿港小鎮〉，收錄在專輯《之乎者也》","en":"Singer Lo Ta-yu wrote a famous song named after Lukang, the old port town here.","ja":"羅大佑の歌「鹿港小鎮」は、アルバム『之乎者也』に収録されている"},{"k":"work","zh":"小說《殺夫》的作者李昂出生在鹿港，許多作品也以鹿港為舞台","en":"Li Ang, author of The Butcher's Wife, was born in Lukang, where many of her stories are set.","ja":"小説『夫殺し』の作者・李昂は鹿港の生まれで、多くの作品の舞台も鹿港"},{"k":"people","zh":"鹿港出身的辜顯榮，1934年成為第一位進入日本貴族院的臺灣人","en":"Lukang-born Koo Hsien-jung became the first Taiwanese member of Japan's House of Peers in 1934.","ja":"鹿港出身の辜顕栄は1934年、台湾人として初めて日本の貴族院議員となった"},{"k":"people","zh":"寫下〈負荷〉的鄉土詩人吳晟，1944年出生在溪州","en":"Poet Wu Sheng, known for writing about farm life, was born in Xizhou here in 1944.","ja":"農村を題材にした詩で知られる詩人の呉晟は、1944年に渓州で生まれた"},{"k":"festival","zh":"鹿港自1978年起舉辦「慶端陽」，2016年龍舟賽首次在夜間舉行","en":"Lukang has held a Dragon Boat Festival celebration since 1978; races were first held at night in 2016.","ja":"鹿港では1978年から端午節の祭典を開き、2016年には竜舟レースを初めて夜間に開催した"},{"k":"life","zh":"鹿港的摸乳巷最窄處只有約70公分，男女錯身難免碰觸而得名","en":"Lukang's cheekily named 'Touch-Breast Lane' is only about 70 cm wide at its narrowest point.","ja":"鹿港の「摸乳巷」は最も狭い所で約70センチ。すれ違うと体が触れることが名の由来"},{"k":"life","zh":"員林曾被媒體稱為「富豪鎮」，流傳有錢人多、律師多、銀行多的「三多」","en":"Yuanlin has been dubbed a 'tycoon town', said to be full of millionaires, lawyers and banks.","ja":"員林はメディアに「富豪の町」と呼ばれ、金持ち・弁護士・銀行が多いと言われる"},{"k":"food","zh":"貓鼠麵得名於創始人瘦小靈活、綽號「老鼠」，臺語可寫作「貓鼠」","en":"Niáu-chhú noodles are named after the founder's nickname, 'Mouse', for his small, nimble build.","ja":"猫鼠麺の名は、小柄で身軽な創業者のあだ名「ネズミ」（台湾語で猫鼠）に由来する"},{"k":"record","zh":"臺灣本島面積最小的縣，約1,074平方公里","en":"It is the smallest county by area on Taiwan's main island, about 1,074 km².","ja":"台湾本島で面積が最も小さい県で、約1,074平方キロ"},{"k":"record","zh":"縣內有6個鎮，是全國鎮數最多的縣","en":"With six urban townships, it has more 'towns' than any other county in Taiwan.","ja":"県内に6つの鎮があり、全国で鎮の数が最も多い県"}],
"TW-CYI":[{"k":"origin","zh":"清代古城的形狀像桃子，所以別稱「桃城」","en":"Its Qing-era walled town was shaped like a peach, giving it the nickname \"Peach City\".","ja":"清代の城郭が桃の形だったため、「桃城」の別名がある"},{"k":"symbol","zh":"市花和市樹都是豔紫荊，市鳥至今還沒定案","en":"Both its city flower and city tree are the Hong Kong orchid tree; its city bird is still undecided.","ja":"市の花も市の木もバウヒニア（豔紫荊）。市の鳥はまだ決まっていない"},{"k":"record","zh":"舊監獄是臺灣唯一完整保存的日治時期監獄，列為國定古蹟","en":"Its old prison is the only fully preserved Japanese-era prison in Taiwan, a national monument.","ja":"旧監獄は台湾で唯一完全に残る日本統治時代の監獄で、国定古跡"},{"k":"festival","zh":"玄天上帝誕辰的「高空盪鞦韆」已有兩百多年歷史","en":"Its \"high swing\" rite on the birthday of Xuantian Shangdi has over 200 years of history.","ja":"玄天上帝の誕生日に行う「高空ブランコ」は200年以上の歴史"},{"k":"people","zh":"許世賢是臺灣第一位女性省轄市長，被譽為「○○媽祖婆」","en":"Hsu Shih-hsien, Taiwan's first female mayor of a provincial city, was hailed as its \"Mazu grandma\".","ja":"許世賢は台湾初の女性の省轄市長で、「○○の媽祖婆」と慕われた"},{"k":"life","zh":"雕刻家詹龍帶動石猴雕刻風潮，讓這裡有了「石猴故鄉」之稱","en":"Sculptor Zhan Long started a craze for stone-monkey carvings, earning it the title \"home of stone monkeys\".","ja":"彫刻家・詹龍が石猿彫刻ブームを起こし、「石猿の故郷」と呼ばれる"},{"k":"record","zh":"臺灣第一個市區公車全面電動化、低底盤化的城市","en":"The first city in Taiwan to make its entire city bus fleet electric and low-floor.","ja":"市内バスを全面電動化・低床化した台湾初の都市"},{"k":"life","zh":"清代的牛墟每月開市九次，牛隻成交後會在牛角繫上紅布帶","en":"Its Qing-era cattle market opened nine times a month; a sold ox got a red ribbon tied on its horn.","ja":"清代の牛市は月9回開かれ、売れた牛の角には赤い布を結んだ"},{"k":"origin","zh":"1787年乾隆帝為褒揚林爽文事件中堅守城池的軍民，下詔改了這座城的名字","en":"In 1787 the Qianlong Emperor renamed the city to honor defenders who held out in the Lin Shuangwen uprising.","ja":"1787年、乾隆帝は林爽文事件で城を守り抜いた軍民をたたえ、町の名を改めた"},{"k":"origin","zh":"舊稱「諸羅山」，源自平埔族洪雅族的社名","en":"Its old name, Zhuluoshan, came from the name of a Hoanya village.","ja":"旧称「諸羅山」は、平埔族ホアニャ族の社名に由来する"},{"k":"origin","zh":"蘭潭原稱「紅毛埤」，是1620年代荷蘭人引八掌溪水開鑿的埤塘","en":"Lantan Lake was once the 'Dutch Pond', dug by the Dutch in the 1620s with water from the Bazhang River.","ja":"蘭潭はもと「紅毛埤」と呼ばれ、1620年代にオランダ人が八掌渓の水を引いて掘った池"},{"k":"life","zh":"戰後曾擬改名為「爽文市」紀念林爽文，但從未實施","en":"After 1945 officials proposed renaming it 'Shuangwen City' after rebel Lin Shuangwen, but it never happened.","ja":"戦後、林爽文を記念して「爽文市」に改名する案があったが、実現しなかった"},{"k":"life","zh":"1982年升格省轄市後，前八屆市長全是女性","en":"After regaining city status in 1982, its first eight mayoral terms were all held by women.","ja":"1982年の省轄市昇格後、最初の8期の市長はすべて女性だった"},{"k":"history","zh":"1906年梅山地震震毀城牆，城門只剩東門","en":"The 1906 Meishan earthquake destroyed the city walls, leaving only the East Gate.","ja":"1906年の梅山地震で城壁が崩れ、城門は東門だけが残った"},{"k":"record","zh":"1989年豎立的彌陀路二二八紀念碑，是臺灣第一座二二八紀念碑","en":"A 1989 monument on Mituo Road was Taiwan's first memorial to the 228 Incident.","ja":"1989年に建てられた弥陀路の二二八記念碑は、台湾初の二二八記念碑"},{"k":"record","zh":"1796年成立的育嬰堂，是臺灣第一座孤兒收容設施","en":"An orphanage founded here in 1796 was the first such institution in Taiwan.","ja":"1796年に設立された育嬰堂は、台湾初の孤児収容施設"},{"k":"record","zh":"2008年啟用的公車捷運，是臺灣第一條BRT系統","en":"Its bus rapid transit, opened in 2008, was Taiwan's first BRT line.","ja":"2008年開業のBRTは、台湾初のバス高速輸送システム"},{"k":"record","zh":"本地畫家林玉山的〈蓮池〉，是第一件被指定為國寶的20世紀畫作","en":"Lotus Pond by local painter Lin Yu-shan was the first 20th-century painting designated a national treasure.","ja":"地元出身の林玉山の「蓮池」は、20世紀の絵画で初めて国宝に指定された"},{"k":"brand","zh":"1946年這裡的酒廠成為臺灣第一個生產高粱酒的酒廠","en":"In 1946 the local winery became the first in Taiwan to produce sorghum liquor.","ja":"1946年、ここの酒工場が台湾で初めてコーリャン酒を生産した"},{"k":"people","zh":"「台展三少年」之一的畫家林玉山，1907年出生在這裡","en":"Painter Lin Yu-shan, one of the 'Three Youths' of the 1927 Taiwan Art Exhibition, was born here in 1907.","ja":"「台展三少年」の一人、画家の林玉山は1907年にここで生まれた"},{"k":"people","zh":"雕塑家蒲添生是本地人，也是畫家陳澄波的女婿","en":"Sculptor Pu Tien-sheng was born here and married the eldest daughter of painter Chen Cheng-po.","ja":"彫刻家の蒲添生はこの地の出身で、画家・陳澄波の長女と結婚した"},{"k":"legend","zh":"1862年戴潮春圍城時，城隍廟籤詩安定民心，後獲光緒帝敕封「綏靖侯」","en":"During the 1862 siege the City God's oracle calmed residents, and in 1875 the emperor granted the god a title.","ja":"1862年の包囲戦で城隍廟のおみくじが民心を鎮め、のちに光緒帝から「綏靖侯」の称号を賜った"},{"k":"festival","zh":"城隍廟每三年舉行「姑爺迎慶」，傳說開漳聖王娶了「十一指」庄的姑娘","en":"Every three years the City God Temple holds a 'son-in-law' festival, from a tale that a god married a local girl.","ja":"城隍廟では3年ごとに「姑爺迎慶」を行う。開漳聖王が地元の娘を娶ったという伝説から"},{"k":"sport","zh":"市立棒球場的前身是1918年啟用的公園野球場，是中職現役最古老的球場","en":"Its city baseball stadium, opened in 1918 as a park ballpark, is the oldest still used by Taiwan's CPBL.","ja":"市立野球場の前身は1918年開場の公園野球場で、台湾プロ野球の現役最古の球場"},{"k":"food","zh":"火雞肉飯源於戰後駐紮的美軍引進火雞，火雞比土雞便宜","en":"Its turkey rice began after WWII when US troops stationed here brought turkeys, cheaper than local chicken.","ja":"七面鳥ご飯は、戦後に駐留米軍が七面鳥を持ち込み、地鶏より安かったことに始まる"},{"k":"food","zh":"方塊酥改良自河北的翻毛月餅與燒餅，把圓形改成了方形","en":"Its square flaky biscuit was adapted from Hebei-style round pastries, simply reshaped into squares.","ja":"方塊酥は河北の翻毛月餅や焼餅を改良し、丸い形を四角にしたもの"}],
"TW-CYQ":[{"k":"symbol","zh":"縣鳥是臺灣特有種藍腹鷴","en":"Its county bird is Swinhoe's pheasant, endemic to Taiwan.","ja":"県の鳥は台湾固有種のサンケイ（藍腹鷴）"},{"k":"record","zh":"外海的外傘頂洲是臺灣最大的濱外沙洲，潟湖面積也是全臺之冠","en":"Waisanding Sandbar offshore is Taiwan's largest barrier sandbar, enclosing its largest lagoon.","ja":"沖合の外傘頂洲は台湾最大の砂州で、潟湖の面積も台湾一"},{"k":"record","zh":"臺灣第一個進入超高齡社會的縣市","en":"The first county or city in Taiwan to become a \"super-aged\" society.","ja":"台湾で最初に超高齢社会に入った県市"},{"k":"life","zh":"笨港水仙宮的屋簷，用臺灣少見的「蹺蹺板」槓桿原理撐住","en":"The roof of Bengang's Shuixian Temple is held up by a seesaw-like lever, rare in Taiwan.","ja":"笨港水仙宮の軒は、台湾では珍しい「シーソー」のてこの原理で支えられている"},{"k":"festival","zh":"民雄大士爺廟每年農曆七月廿一至廿三舉辦「大士爺文化祭」","en":"Minxiong's Dashiye Temple holds the Dashiye Festival on the 21st to 23rd of the 7th lunar month.","ja":"民雄の大士爺廟で毎年旧暦7月21～23日に「大士爺文化祭」が開かれる"},{"k":"work","zh":"〈高山青〉出自電影《阿里山風雲》，那是臺灣戰後拍的第一部國語片","en":"The song \"Gao Shan Qing\" comes from the film Storm Over Alishan, Taiwan's first postwar Mandarin film.","ja":"歌「高山青」は映画『阿里山風雲』の主題歌。戦後台湾で初めての北京語映画"},{"k":"origin","zh":"民雄舊稱「打貓」，1920年改成日語讀音相近的「民雄」（たみお）","en":"Minxiong was once \"Tá-niau\" (Hit Cat); in 1920 it was renamed for a similar Japanese reading, Tamio.","ja":"民雄の旧名は「打猫」。1920年、日本語読みが近い「民雄（たみお）」に改名"},{"k":"life","zh":"名產新港飴的外形像老鼠，最早叫「老鼠仔糖」","en":"The local Xingang candy looked like a mouse and was first called \"mouse candy\".","ja":"名物の新港飴はネズミの形で、もとは「老鼠仔糖」と呼ばれた"},{"k":"origin","zh":"縣治太保市的地名，來自清代名將王得祿官拜「太子太保」","en":"The county seat Taibao is named after Qing general Wang De-lu, who held the title Grand Guardian of the Crown Prince.","ja":"県庁所在地の太保は、清代の名将・王得禄が「太子太保」の官位を得たことに由来する"},{"k":"people","zh":"搖滾歌手伍佰（本名吳俊霖）出生在○○六腳鄉蒜頭村","en":"Rock singer Wu Bai (Wu Chun-lin) was born in Suantou Village, Liujiao Township, here.","ja":"ロック歌手の伍佰（本名・呉俊霖）は○○の六脚郷蒜頭村の生まれ"},{"k":"brand","zh":"泡麵發明人安藤百福，1910年出生在○○的朴子","en":"Momofuku Ando, inventor of instant noodles, was born in Puzi here in 1910.","ja":"インスタントラーメンを発明した安藤百福は、1910年に○○の朴子で生まれた"},{"k":"people","zh":"人稱「台灣交趾第一人」的清代陶藝家葉王，家族定居在民雄","en":"Qing potter Ye Wang, hailed as Taiwan's first master of Koji pottery, came from a family settled in Minxiong here.","ja":"「台湾交趾焼の第一人者」と称される清代の陶芸家・葉王は、民雄に定住した一家の出身"},{"k":"sport","zh":"1979年朴子國小少棒隊奪下世界少棒大賽冠軍","en":"In 1979 Puzi Elementary School's Little League team won the Little League World Series.","ja":"1979年、朴子国民小学の少年野球チームがリトルリーグ・ワールドシリーズで優勝した"},{"k":"festival","zh":"朴子配天宮每年農曆三月廿二、廿三日舉行媽祖出巡遶境","en":"Peitian Temple in Puzi holds its Mazu procession on the 22nd and 23rd of the third lunar month.","ja":"朴子の配天宮では毎年旧暦3月22・23日に媽祖の巡行が行われる"},{"k":"origin","zh":"東石鄉的先民來自泉州晉江的東石，便沿用故鄉地名","en":"Dongshi was settled by people from Dongshi in Jinjiang, Fujian, who kept their hometown's name.","ja":"東石郷は泉州晋江の東石から渡ってきた人々が、故郷の名をそのまま付けた"},{"k":"origin","zh":"朴子舊稱「樸仔腳」，因媽祖廟最早蓋在一棵朴樹下而得名","en":"Puzi takes its name from a Chinese hackberry tree under which a Mazu shrine was first built.","ja":"朴子の旧名は「樸仔脚」で、エノキの木の下に媽祖廟が建てられたことに由来する"},{"k":"origin","zh":"奮起湖其實沒有湖，舊名「畚箕湖」形容三面環山的山坳","en":"Fenqihu has no lake: its old name meant 'dustpan hollow', a basin ringed by mountains on three sides.","ja":"奮起湖に湖はなく、旧名「畚箕湖」は三方を山に囲まれた窪地をちりとりに見立てたもの"},{"k":"origin","zh":"梅山原稱「小梅」，居民嫌名字太柔弱，1946年改成現名","en":"Meishan was once 'Xiaomei' (Little Plum); residents found it too feeble and renamed it in 1946.","ja":"梅山はかつて「小梅」と呼ばれたが、住民が弱々しいと嫌い1946年に改名した"},{"k":"history","zh":"1750年洪水把笨港一分為二，南街居民後來遷居建立新港","en":"A 1750 flood split the port town of Bengang in two; its southern residents later moved away and founded Xingang.","ja":"1750年の洪水で笨港が南北に分かれ、南街の住民がのちに移って新港を築いた"},{"k":"history","zh":"2000年番路鄉八掌溪有四名工人受困，直升機遲未出動，在直播下被沖走","en":"In 2000 four workers trapped in the Bazhang River at Fanlu were swept away on live TV as helicopters never came.","ja":"2000年、番路郷の八掌渓で取り残された作業員4人が、救助ヘリが来ないまま生中継の中で流された"},{"k":"history","zh":"1989年吳鳳鄉改名，吳鳳捨身取義的故事也從課本刪除","en":"In 1989 Wufeng Township was renamed Alishan, and the Wu Feng self-sacrifice myth was dropped from textbooks.","ja":"1989年に呉鳳郷は阿里山郷へ改名され、呉鳳の自己犠牲の物語も教科書から消えた"},{"k":"record","zh":"布袋的玻璃高跟鞋教堂高17.76公尺，2016年獲金氏世界紀錄","en":"Budai's glass High-Heel Church, 17.76 m tall, set a Guinness record in 2016 as the largest shoe-shaped building.","ja":"布袋のガラスのハイヒール教会は高さ17.76mで、2016年にギネス世界記録に認定された"},{"k":"life","zh":"高跟鞋教堂的造型，紀念因烏腳病截肢、無法穿高跟鞋出嫁的女性","en":"The High-Heel Church honors local women who lost their feet to blackfoot disease and could not wear heels to wed.","ja":"ハイヒール教会の形は、烏脚病で足を失いハイヒールで嫁げなかった女性たちを偲ぶもの"},{"k":"food","zh":"蒸汽火車在奮起湖加水加煤、停靠近午，就此形成鐵路便當文化","en":"Steam trains stopped at Fenqihu for water and coal near noon, so passengers ate there, giving rise to its railway bento.","ja":"蒸気機関車が昼前に奮起湖で給水・給炭のため停車し、駅弁文化が生まれた"},{"k":"nature","zh":"東石的鰲鼓濕地原是台糖造陸農場，因地層下陷才變成濕地","en":"Aogu Wetland in Dongshi was reclaimed sugar-company farmland that turned into wetland as the ground subsided.","ja":"東石の鰲鼓湿地は台糖の干拓農地が、地盤沈下で湿地に変わったもの"},{"k":"legend","zh":"民雄的劉家古厝建於1929年，是臺灣最出名的鬼屋之一","en":"Built in 1929, the Liu family mansion in Minxiong is one of Taiwan's most famous haunted houses.","ja":"1929年築の民雄・劉家古厝は、台湾で最も有名な幽霊屋敷の一つ"},{"k":"life","zh":"達邦與特富野的鄒族男子會所「庫巴」，只有男性能進入","en":"In the Tsou villages of Tapangu and Tfuya, the kuba men's house may be entered only by men.","ja":"ツォウ族の達邦・特富野にある男子集会所「クバ」には、男性しか入れない"},{"k":"history","zh":"布袋鹽場從1784年開始曬鹽，直到2001年才停產","en":"The Budai salt fields produced sea salt from 1784 until 2001.","ja":"布袋の塩田は1784年から2001年まで塩を作り続けた"},{"k":"nature","zh":"梅山的太平雲梯是架在海拔約千公尺、長281公尺的吊橋","en":"Taiping Cloud Ladder in Meishan is a 281 m suspension bridge at about 1,000 m elevation.","ja":"梅山の太平雲梯は、標高約1000mに架かる長さ281mの吊り橋"}],
"TW-HSQ":[{"k":"work","zh":"漫畫《阿三哥與大嬸婆》作者劉興欽的故鄉，內灣用他筆下的角色打造商圈","en":"Hometown of Liu Hsing-chin, creator of the comic A-San Ge and Aunt Da-shen; Neiwan uses his characters.","ja":"漫画『阿三哥と大嬸婆』の作者・劉興欽の故郷。内湾の街は彼のキャラで彩られる"},{"k":"work","zh":"電影《九降風》主要在竹東高中拍攝，講1990年代一群愛棒球的高中男生","en":"The film Winds of September was shot mainly at Zhudong High School, about baseball-loving boys in the 1990s.","ja":"映画『九月に降る風』は主に竹東高校で撮影。1990年代の野球好きの高校生の物語"},{"k":"people","zh":"作家三毛曾住在五峰鄉的清泉，故居被稱為「三毛夢屋」","en":"Writer Sanmao once lived in Qingquan, Wufeng; her house is known as \"Sanmao's Dream House\".","ja":"作家・三毛は五峰郷の清泉に住んだことがあり、旧居は「三毛夢屋」と呼ばれる"},{"k":"people","zh":"《亞細亞的孤兒》作者吳濁流在這裡出生長大","en":"Wu Zhuoliu, author of Orphan of Asia, was born and raised here.","ja":"『アジアの孤児』の作者・呉濁流はここで生まれ育った"},{"k":"symbol","zh":"縣鳥是五色鳥，縣樹是竹柏","en":"Its county bird is the Taiwan barbet; its county tree is the nagi podocarp.","ja":"県の鳥はゴシキドリ（五色鳥）、県の木はナギ（竹柏）"},{"k":"sport","zh":"職籃攻城獅的主場在這裡的縣立體育館","en":"The Lioneers pro basketball team plays its home games at the county gymnasium here.","ja":"プロバスケ「攻城獅（ライオニアーズ）」の本拠地は県立体育館"},{"k":"origin","zh":"尖石鄉的名字，來自兩條溪匯流處一塊像竹筍般聳立的巨石","en":"Jianshi Township is named after a huge rock rising like a bamboo shoot where two creeks meet.","ja":"尖石郷の名は、二つの渓流が合わさる所にタケノコのようにそびえる巨石から"},{"k":"record","zh":"尖石鄉同時和兩個直轄市接壤，全臺只有兩個鄉鎮如此","en":"Jianshi borders two special municipalities at once, one of only two townships in Taiwan that do.","ja":"尖石郷は二つの直轄市と接する、台湾で二つしかない郷の一つ"},{"k":"legend","zh":"相傳賽夏族與矮人隔著上坪溪而居，族人鋸斷矮人歇息的山枇杷樹讓他們墜崖","en":"Saisiyat legend: little people lived across the Shangping River until a sawn loquat tree sent them off a cliff.","ja":"上坪渓を挟んで小人と暮らしたサイシャット族が、小人の休む山ビワの木を切り崖下に落としたという伝説がある"},{"k":"festival","zh":"賽夏族北祭團的矮靈祭在五峰鄉大隘村舉行，每兩年一次","en":"The Saisiyat northern group holds its Pas-ta'ai ritual in Dai Village, Wufeng, every two years.","ja":"サイシャット族北祭団の矮霊祭は、五峰郷大隘村で2年に一度行われる"},{"k":"history","zh":"1907年北埔事件，蔡清琳等人率客家人與賽夏族人襲擊日方據點","en":"In the 1907 Beipu Incident, Hakka and Saisiyat fighters led by Tsai Ching-lin attacked Japanese posts.","ja":"1907年の北埔事件では、蔡清琳らが客家人とサイシャット族を率いて日本側の拠点を襲った"},{"k":"people","zh":"1895年乙未戰爭時，北埔的姜紹祖組織「敢字營」義勇軍抗日","en":"During the 1895 Japanese invasion, Jiang Shaozu of Beipu formed a volunteer militia to resist.","ja":"1895年の乙未戦争で、北埔の姜紹祖は義勇軍「敢字営」を組織して日本軍に抵抗した"},{"k":"people","zh":"北埔出身的龍瑛宗，以〈植有木瓜樹的小鎮〉獲東京《改造》雜誌小說佳作","en":"Beipu-born Long Yingzong won a Kaizo magazine fiction prize in 1937 for The Town with Papaya Trees.","ja":"北埔出身の龍瑛宗は1937年、「パパイヤのある街」で雑誌『改造』の懸賞小説佳作に入った"},{"k":"life","zh":"深山的司馬庫斯部落直到1979年才通電，曾被稱為「黑暗部落」","en":"The remote Smangus village got electricity only in 1979 and was once called the 'dark tribe'.","ja":"山奥のスマングス集落は1979年にようやく電気が通り、「暗黒の部落」と呼ばれた"},{"k":"life","zh":"司馬庫斯部落仿效以色列集體農場，採取共同經營制度","en":"Smangus runs its community on a cooperative model inspired by Israel's kibbutzim.","ja":"スマングス集落は、イスラエルのキブツにならった共同経営の仕組みをとっている"},{"k":"origin","zh":"新豐鄉原名「紅毛鄉」，1956年才改成今名","en":"Xinfeng Township was called 'Hongmao (Red-Hair)' until 1956.","ja":"新豊郷の旧名は「紅毛郷」で、1956年に現在の名に改められた"},{"k":"origin","zh":"五峰鄉的清泉溫泉，日治時期名叫「井上溫泉」","en":"Qingquan Hot Spring in Wufeng was called 'Inoue Hot Spring' under Japanese rule.","ja":"五峰郷の清泉温泉は、日本統治時代「井上温泉」と呼ばれていた"},{"k":"origin","zh":"境內一個鎮舊名「樹杞林」，取自漢人初到時看見的大片樹杞","en":"One town here was once called Shuqilin, after the dense shuqi trees early Han settlers found.","ja":"域内のある鎮の旧名「樹杞林」は、漢人が来た頃に茂っていた樹杞の林に由来する"},{"k":"origin","zh":"峨眉鄉舊名「月眉」，因溪岸半月形的台地得名，1904年改名","en":"Emei Township was once 'Yuemei (Crescent Brow)', after a half-moon terrace by the creek; renamed in 1904.","ja":"峨眉郷の旧名「月眉」は渓流沿いの半月形の段丘に由来し、1904年に改名された"},{"k":"history","zh":"1950年行政區調整，桃園與苗栗都從這個縣分了出去","en":"In 1950, Taoyuan and Miaoli were split off from this county.","ja":"1950年の再編で、桃園と苗栗がこの県から分離した"},{"k":"history","zh":"1910至1913年的李崠山事件，總督佐久間左馬太曾親自坐鎮督戰","en":"During the 1910-13 Lidongshan campaign, Governor-General Sakuma Samata personally directed the fighting.","ja":"1910〜13年の李崠山事件では、佐久間左馬太総督が自ら現地で指揮を執った"},{"k":"nature","zh":"尖石鄉的馬里闊丸溪（玉峰溪）是淡水河的源流","en":"The Malikoan (Yufeng) Creek in Jianshi is a headwater of the Tamsui River.","ja":"尖石郷の馬里闊丸渓（玉峰渓）は、淡水河の源流である"},{"k":"nature","zh":"新豐溪的河口，有十多公頃的紅樹林","en":"The mouth of the Xinfeng River has over ten hectares of mangroves.","ja":"新豊渓の河口には、10ヘクタールを超えるマングローブ林が広がる"},{"k":"nature","zh":"頭前溪的上源霞喀羅溪，發源於海拔2,512公尺的檜山","en":"The Xiakeluo River, source of the Touqian River, rises on 2,512 m Mount Gui.","ja":"頭前渓の上流・霞喀羅渓は、標高2,512メートルの檜山に源を発する"},{"k":"brand","zh":"境內一個鎮曾與東勢、羅東並稱臺灣三大林業集散地","en":"One town here was among Taiwan's three great timber hubs, along with Dongshi and Luodong.","ja":"域内のある鎮は、東勢・羅東と並ぶ台湾三大林業集散地の一つだった"},{"k":"nature","zh":"尖石鄉鎮西堡有兩百多棵紅檜巨木，1986年居民抗爭讓林務局停止砍伐","en":"Cinsbu in Jianshi has 200+ giant cypresses; a 1986 protest by locals stopped logging there.","ja":"尖石郷の鎮西堡には200本以上の巨木があり、1986年に住民の抗議で伐採が止まった"},{"k":"people","zh":"女子團體S.H.E的成員田馥甄出身這裡","en":"Hebe Tien of the girl group S.H.E is from here.","ja":"女性グループS.H.Eのメンバー、田馥甄（ヒビ・ティエン）はここの出身だ"}],
"TW-HSZ":[{"k":"origin","zh":"古名「竹塹」，源自平埔族道卡斯族的「竹塹社」","en":"Its old name Zhuqian comes from Tek-chham, a village of the Taokas people.","ja":"古名「竹塹」は、平埔族タオカス族の「竹塹社」に由来する"},{"k":"people","zh":"前臺北市長柯文哲的出生地","en":"Birthplace of Ko Wen-je, former mayor of Taipei.","ja":"元台北市長・柯文哲の出生地"},{"k":"symbol","zh":"市樹是黑松","en":"Its official tree is the Japanese black pine.","ja":"市の木はクロマツ"},{"k":"record","zh":"臺灣最早使用瓦斯的地方，1936年還設立了天然瓦斯研究所","en":"The first place in Taiwan to use gas; a natural gas research institute was founded here in 1936.","ja":"台湾で最初にガスが使われた地。1936年には天然ガス研究所も設立された"},{"k":"record","zh":"香山是臺灣最北、也最晚收成的荔枝產地，每年六、七月採收","en":"Xiangshan is Taiwan's northernmost and latest-harvesting lychee area, picked in June and July.","ja":"香山は台湾最北で収穫が最も遅いライチ産地。6～7月に収穫"},{"k":"life","zh":"1960年代臺灣是全球生產聖誕燈泡最多的地區，靠的是這座城市全城趕工","en":"In the 1960s Taiwan made more Christmas bulbs than anywhere, thanks to this whole city working overtime.","ja":"1960年代、台湾は世界一のクリスマス電球産地。この街が総出で作っていた"},{"k":"life","zh":"東區關新里的所得總額中位數，曾是2017年度的全臺之冠","en":"Guanxin Village in its East District had Taiwan's highest median income in 2017.","ja":"東区関新里の所得中央値は、2017年度に台湾一だった"},{"k":"people","zh":"清代帶族人來此開墾的同安人王世傑，竹蓮寺至今供奉他的長生祿位","en":"Wang Shih-chieh led settlers here in the Qing era; Zhulian Temple still honors him with a longevity tablet.","ja":"清代に一族を率いて開墾した同安出身の王世傑は、竹蓮寺に長生禄位が祀られている"},{"k":"history","zh":"1733年淡水廳治移到這裡，以莿竹圍成城牆","en":"In 1733, the Tamsui Subprefecture seat moved here, and a wall of thorny bamboo was built.","ja":"1733年に淡水庁の役所がここへ移り、トゲのある竹で城壁が築かれた"},{"k":"history","zh":"1998年國華航空墜機事故後，市內機場停止民航","en":"After a 1998 Formosa Airlines crash, the local airport ended civilian flights.","ja":"1998年の国華航空墜落事故以降、市内の空港は民間航路を廃止した"},{"k":"history","zh":"1626年西班牙佔領北臺灣後，天主教傳教士就來到這一帶","en":"Catholic missionaries reached this settlement in 1626, after the Spanish took northern Taiwan.","ja":"1626年、スペインの北台湾占領後にカトリックの宣教師がこの集落に来た"},{"k":"record","zh":"1913年完工的火車站，是臺灣現存最古老且仍在使用的車站站房","en":"The railway station, completed in 1913, is Taiwan's oldest station building still in use.","ja":"1913年完成の駅舎は、台湾に現存する最古の現役駅舎だ"},{"k":"history","zh":"1890年光緒帝賜「金門保障」匾，並把這裡的城隍晉封為都城隍","en":"In 1890 the Guangxu Emperor promoted the local City God to 'Capital City God' and granted a plaque.","ja":"1890年、光緒帝が「金門保障」の扁額を下賜し、ここの城隍神を都城隍に昇格させた"},{"k":"festival","zh":"每年農曆七月十五，城隍爺親自出巡「繞境賑孤」","en":"On the 15th day of the 7th lunar month, the City God tours the streets to aid wandering spirits.","ja":"毎年旧暦7月15日、城隍神が自ら町を巡り孤魂を救う「遶境賑孤」が行われる"},{"k":"legend","zh":"傳說清朝皇子漂流到臺灣，官員靠城隍爺指點找到他，城隍因此晉升","en":"Legend says a Qing prince drifted to Taiwan and officials found him with the City God's guidance.","ja":"清の皇子が台湾に流れ着き、役人が城隍神のお告げで見つけたため城隍が昇格したと伝わる"},{"k":"legend","zh":"傳說城隍廟坐落在「鯉魚穴」的魚臍上，附近各廟是魚頭與魚尾","en":"Legend says the City God Temple sits on the navel of a 'carp lair', with nearby temples as head and tail.","ja":"城隍廟は「鯉魚穴」のへその位置に建ち、周りの廟が頭と尾にあたるという言い伝えがある"},{"k":"life","zh":"早年城隍爺繞境會到鄭氏家廟休息，享用奉茶與燕窩，稱為「鄭厝貢燕」","en":"On old processions the City God rested at the Cheng family shrine and was offered tea and bird's nest.","ja":"昔の巡行では城隍神が鄭氏家廟で休み、茶と燕の巣を供えられた（鄭厝貢燕）"},{"k":"people","zh":"1986年諾貝爾化學獎得主李遠哲在這裡出生","en":"Yuan T. Lee, winner of the 1986 Nobel Prize in Chemistry, was born here.","ja":"1986年にノーベル化学賞を受けた李遠哲は、ここの出身だ"},{"k":"sport","zh":"1968年奧運田徑銅牌得主紀政，出身這座城市","en":"Chi Cheng, who won an Olympic track and field bronze in 1968, is from here.","ja":"1968年五輪の陸上競技で銅メダルを獲得した紀政は、この市の出身だ"},{"k":"sport","zh":"曾登上女子網球雙打世界第一的謝淑薇，出身這座城市","en":"Hsieh Su-wei, a former world No. 1 in women's doubles tennis, is from here.","ja":"女子テニスのダブルスで世界1位になった謝淑薇は、この市の出身だ"},{"k":"sport","zh":"1976年落成的中正棒球場，原本計畫命名為「王貞治紀念棒球場」","en":"The city's baseball stadium, built in 1976, was originally to be named after Sadaharu Oh.","ja":"1976年完成の中正野球場は、当初「王貞治記念野球場」と名付けられる予定だった"},{"k":"people","zh":"被稱為臺灣第一位女詩人的陳秀喜，是這座城市的作家","en":"Chen Hsiu-hsi, called Taiwan's first woman poet, was a writer from this city.","ja":"台湾初の女性詩人とされる陳秀喜は、この市ゆかりの作家だ"},{"k":"people","zh":"日本小說家埴谷雄高在日治時期出生於這裡","en":"Japanese novelist Yutaka Haniya was born here during Japanese rule.","ja":"日本の小説家・埴谷雄高は、日本統治時代のこの地で生まれた"},{"k":"food","zh":"清代福建惠安移民把米粉製法帶來，直到1960年代這裡都是米粉業重鎮","en":"Settlers from Hui'an, Fujian, brought rice-noodle making here in the Qing era; it stayed a hub into the 1960s.","ja":"清代に福建・恵安の移民がビーフン作りを伝え、1960年代までその一大産地だった"},{"k":"brand","zh":"外海的長康油田在1986年開始生產天然氣與原油","en":"The offshore CBK oil field began producing natural gas and crude oil in 1986.","ja":"沖合の長康油田は、1986年に天然ガスと原油の生産を始めた"},{"k":"symbol","zh":"代表這座城市的市鳥是喜鵲，市花是杜鵑花","en":"The city bird is the Eurasian magpie, and the city flower is the azalea.","ja":"この市の市鳥はカササギ、市花はツツジである"}],
"TW-HUA":[{"k":"origin","zh":"古稱「洄瀾」，傳說溪水奔入大海與浪交會迴旋而得名，後取諧音改成今名","en":"Once called Huilan (swirling waves), for where the river meets the sea; the current name came from its similar sound.","ja":"古名「洄瀾」は、川が海に注ぎ波と渦巻く様から。のちに音の近い現名に"},{"k":"symbol","zh":"縣鳥是朱鸝","en":"Its county bird is the maroon oriole.","ja":"県の鳥はアカハラコウライウグイス（朱鸝）"},{"k":"record","zh":"1950年成為第一個依憲法實施地方自治的縣市，首任縣長有「華人第一位民選縣長」之說","en":"In 1950 it was the first to adopt constitutional local self-rule; its first magistrate is called the Chinese world's first elected one.","ja":"1950年、憲法による地方自治を最初に実施。初代県長は華人社会初の民選県長とも"},{"k":"record","zh":"玉里鎮是臺灣面積最大的「鎮」","en":"Yuli is the largest town (zhen) in Taiwan by area.","ja":"玉里鎮は面積が台湾最大の「鎮」"},{"k":"work","zh":"電影《太陽的孩子》以豐濱鄉的阿美族港口部落為舞台","en":"The film Wawa No Cidal is set in the Amis community of Makotaay in Fengbin.","ja":"映画『太陽の子』の舞台は豊浜郷のアミ族・港口集落"},{"k":"life","zh":"瑞穗溫泉略帶金黃色，有「生男之泉」的美名","en":"Ruisui Hot Spring, slightly golden in color, is nicknamed the \"spring for having sons\".","ja":"瑞穂温泉はやや金色を帯び、「男の子を授かる湯」と呼ばれる"},{"k":"people","zh":"詩人楊牧、小說家王禎和都出身這裡","en":"Poet Yang Mu and novelist Wang Chen-ho both came from here.","ja":"詩人・楊牧と小説家・王禎和はともにここの出身"},{"k":"sport","zh":"每年都有一場在大理石峽谷中奔跑的「太魯閣峽谷馬拉松」","en":"It hosts the Taroko Gorge Marathon, run through a marble gorge.","ja":"大理石の峡谷を走る「太魯閣峡谷マラソン」が開かれる"},{"k":"history","zh":"1622年西班牙人來這裡採砂金，稱此地為「多羅滿」","en":"In 1622 Spaniards came here to pan for gold, calling the area Turoboan.","ja":"1622年、スペイン人が砂金採りに訪れ、この地を「多羅満」と呼んだ"},{"k":"origin","zh":"舊稱「奇萊」，日治時期因日語發音近似「討厭（嫌い）」而避用","en":"The Japanese avoided the old name Kiray because it sounded like the Japanese word for \"dislike.\"","ja":"旧称「奇萊（キライ）」は日本語の「嫌い」に聞こえるため、日本統治時代には避けられた"},{"k":"life","zh":"1932年臨海道路通車前，往來多半只能搭船，因此有「陸上離島」之稱","en":"Until a coastal road opened in 1932 it was reached mostly by ship, earning the nickname \"island on land.\"","ja":"1932年に臨海道路が開通するまでは船で行き来するしかなく、「陸の離島」と呼ばれた"},{"k":"history","zh":"1914年日軍與太魯閣族爆發戰爭，是二十世紀臺灣本島最大的戰役","en":"The 1914 Truku War between Japan and the Truku people was the largest battle on Taiwan island in the 20th century.","ja":"1914年の日本軍とタロコ族の戦争は、20世紀の台湾本島で最大の戦役だった"},{"k":"history","zh":"臺灣總督佐久間左馬太在太魯閣戰爭前線視察時墜崖受傷，隔年去世","en":"Governor-General Sakuma Samata fell off a cliff while inspecting the Truku War front and died the next year.","ja":"台湾総督の佐久間左馬太はタロコ戦争の前線視察中に崖から落ちて負傷し、翌年亡くなった"},{"k":"history","zh":"1878年加禮宛事件中撒奇萊雅族遭清軍火攻，倖存者隱身阿美族中百餘年","en":"After Qing troops burned their village in 1878, surviving Sakizaya hid among the Amis for over a century.","ja":"1878年に清軍に集落を焼かれたサキザヤ族は、その後百年以上アミ族の中に身を隠した"},{"k":"record","zh":"2007年撒奇萊雅族正名，成為臺灣第13個原住民族","en":"In 2007 the Sakizaya, based here, became Taiwan's 13th officially recognized Indigenous people.","ja":"2007年、ここを拠点とするサキザヤ族が台湾で13番目の原住民族として認められた"},{"k":"festival","zh":"撒奇萊雅族的火神祭停辦128年後，2006年在國福部落重新舉行","en":"The Sakizaya Fire God Ceremony was revived here in 2006 after a 128-year gap.","ja":"サキザヤ族の火神祭は128年途絶えた後、2006年に国福部落で復活した"},{"k":"people","zh":"周杰倫的御用詞人方文山出生於富里鄉，寫下〈青花瓷〉等名曲","en":"Lyricist Vincent Fang, who wrote Jay Chou's \"Blue and White Porcelain,\" was born in Fuli Township here.","ja":"周杰倫の作詞家として知られる方文山は富里郷の生まれで、「青花瓷」などを手がけた"},{"k":"brand","zh":"證嚴法師1966年在這裡創立慈濟功德會，總部靜思精舍也在縣內","en":"Master Cheng Yen founded the Tzu Chi merit society here in 1966; its headquarters, the Jing Si Abode, is here too.","ja":"證厳法師は1966年にここで慈済功徳会を創設し、本部の静思精舎も県内にある"},{"k":"record","zh":"天主教徒占人口的比例是全臺各縣市最高","en":"It has the highest share of Roman Catholics of any county or city in Taiwan.","ja":"カトリック信者の割合が台湾の県市で最も高い"},{"k":"life","zh":"與日本最西端的與那國町、宮崎縣的高千穗町都是姊妹市","en":"Its sister cities include Yonaguni, Japan's westernmost town, and Takachiho in Miyazaki.","ja":"日本最西端の与那国町や宮崎県高千穂町と姉妹都市になっている"},{"k":"brand","zh":"新城鄉的亞洲水泥廠是臺灣主要的水泥產地之一","en":"Xincheng Township's Asia Cement plant is one of Taiwan's main sources of cement.","ja":"新城郷のアジアセメント工場は、台湾の主要なセメント産地の一つだ"},{"k":"life","zh":"縣治所在的市與鄰近的新城鄉，面積同為29.4095平方公里","en":"The county seat city and neighboring Xincheng Township have exactly the same area: 29.4095 km².","ja":"県庁所在地の市と隣の新城郷は、面積がどちらも29.4095平方キロで全く同じだ"},{"k":"food","zh":"名產「○○薯」是1899年日本人開的餅舖研發的點心，還曾進貢日本皇室","en":"Its famous sweet-potato pastry was created in 1899 by a Japanese-run shop and was once sent to Japan's imperial family.","ja":"名物の芋菓子は1899年に日本人の菓子店が考案したもので、皇室への献上品にもなった"},{"k":"history","zh":"長春祠供奉開鑿中橫公路時殉職的225位榮民","en":"Eternal Spring Shrine honors 225 veterans who died building the Central Cross-Island Highway.","ja":"長春祠には、中部横貫公路の建設で殉職した225人の退役軍人が祀られている"},{"k":"history","zh":"松園別館原是二戰時日本陸軍在此的最高指揮中心，因周圍的琉球松得名","en":"Pine Garden was the Japanese army's top command post here in WWII and is named for its Ryukyu pines.","ja":"松園別館は戦時中の日本陸軍の最高司令部で、周囲の琉球松が名の由来だ"},{"k":"nature","zh":"境內有43座臺灣百岳，奇萊山也在其中","en":"43 of Taiwan's \"100 Peaks\" lie within the county, including Mt. Qilai.","ja":"台湾百岳のうち43座が県内にあり、奇萊山もその一つだ"},{"k":"nature","zh":"海岸山脈的最高峰新港山（1,682公尺）位在縣內","en":"The Coastal Range's highest summit, Mt. Xingang (1,682 m), lies in this county.","ja":"海岸山脈の最高峰・新港山（1682メートル）は県内にある"},{"k":"history","zh":"2021年太魯閣號在清水隧道出軌，是1948年以來臺灣最嚴重的鐵道事故","en":"The 2021 Taroko Express derailment at Qingshui Tunnel was Taiwan's deadliest train accident since 1948.","ja":"2021年、清水トンネルでタロコ号が脱線し、1948年以来最悪の鉄道事故となった"}],
"TW-ILA":[{"k":"origin","zh":"清代舊名「蛤仔難」，源自當地原住民族的族名，意思是「平原的人」","en":"Its old name Kap-a-lan comes from the Kavalan people, whose name means \"people of the plain\".","ja":"旧名「蛤仔難（カバラン）」は先住民族の名に由来し、「平野の人」の意"},{"k":"people","zh":"繪本作家幾米出生在羅東，火車站旁還有以他繪本為主題的廣場","en":"Picture-book artist Jimmy Liao was born in Luodong; a plaza by the main train station features his art.","ja":"絵本作家ジミー・リャオは羅東生まれ。駅のそばには彼の絵本の広場がある"},{"k":"festival","zh":"礁溪二龍村的端午龍舟賽沒有裁判、不鳴槍，槳手跪著划，勝負由大家自己認定","en":"Erlong Village's dragon boat race has no referee or starting gun; paddlers kneel, and everyone judges the winner.","ja":"礁渓・二龍村の端午のレースは審判も号砲もなし。漕ぎ手はひざまずき、勝敗は皆で決める"},{"k":"symbol","zh":"縣鳥是彩鷸","en":"Its county bird is the greater painted-snipe.","ja":"県の鳥はタマシギ（彩鷸）"},{"k":"record","zh":"太平山上的翠峰湖是臺灣最大的高山湖泊","en":"Cuifeng Lake on Taipingshan is Taiwan's largest alpine lake.","ja":"太平山の翠峰湖は台湾最大の高山湖"},{"k":"record","zh":"南方澳南天宮的金媽祖用約200公斤純金打造，是臺灣最早的金媽祖","en":"Nantian Temple in Nanfang'ao has a Mazu statue of about 200 kg of pure gold, Taiwan's first golden Mazu.","ja":"南方澳・南天宮の金の媽祖像は純金約200kg。台湾で最初の金媽祖"},{"k":"people","zh":"1787年吳沙率約兩百名移民入墾，被稱為「開○第一人」","en":"In 1787 Wu Sha led some 200 settlers here and is hailed as the region's first pioneer.","ja":"1787年、呉沙が約200人の移民を率いて開墾し、「開拓の第一人者」と称される"},{"k":"life","zh":"五結、頭圍這類帶「結」「圍」的地名，源自清代十幾人一結、數十結一圍的開墾編組","en":"Place names with \"jie\" and \"wei\" (Wujie, Touwei) come from Qing settler units: a dozen men per jie, dozens of jie per wei.","ja":"五結・頭囲など「結」「囲」の付く地名は、清代の開墾組織（十数人で一結、数十結で一囲）から"},{"k":"history","zh":"太平洋戰爭時日軍在此建機場供神風特攻隊出擊，農校學生還被要求做假飛機騙美軍","en":"In WWII Japan built a kamikaze airfield here, and farm-school students made fake planes to fool US bombers.","ja":"太平洋戦争中、日本軍がここに特攻隊用の飛行場を造り、農学校の生徒は米軍を欺く偽の飛行機を作らされた"},{"k":"history","zh":"台塑六輕原本規劃設廠在這裡，因地方強烈反對，最後改設到雲林","en":"Formosa Plastics' Sixth Naphtha Cracker was first planned here, but local protests pushed it to Yunlin.","ja":"台湾プラスチックの第六ナフサ工場は当初ここに計画されたが、地元の強い反対で雲林へ移された"},{"k":"history","zh":"1950年才從臺北縣劃出12個鄉鎮，獨立設縣","en":"It became a separate county only in 1950, when 12 townships were split off from Taipei County.","ja":"1950年に台北県から12の郷鎮が分かれ、ようやく独立した県になった"},{"k":"history","zh":"1632年一艘西班牙船遇颶風漂到這裡，是當地原住民族最早的文獻記載","en":"In 1632 a Spanish ship blown off course by a storm landed here, the earliest record of the local Indigenous people.","ja":"1632年、嵐で流されたスペイン船がここに漂着し、これが当地の先住民に関する最古の記録となった"},{"k":"history","zh":"1875年牡丹社事件之後，清廷把這裡由「廳」改制為縣","en":"After the Mudan Incident, the Qing turned this district from a subprefecture into a county in 1875.","ja":"牡丹社事件の後、1875年に清朝はこの地を「庁」から県に改めた"},{"k":"people","zh":"1981年黨外的陳定南當選縣長，是這裡第一位非國民黨籍縣長","en":"In 1981 Chen Ding-nan, backed by the Tangwai movement, became the first non-KMT magistrate here.","ja":"1981年、党外の陳定南が当選し、ここで初めての国民党以外の県長となった"},{"k":"people","zh":"臺灣民眾黨創辦人蔣渭水生於這裡，國道五號也以他命名","en":"Chiang Wei-shui, founder of the Taiwanese People's Party, was born here; Freeway 5 is named after him.","ja":"台湾民衆党を創設した蒋渭水はここの出身で、国道5号は彼の名を冠している"},{"k":"life","zh":"民進黨支持者稱這裡為「民主聖地」","en":"Supporters of the DPP call this county the \"Sacred Place of Democracy.\"","ja":"民進党の支持者からは「民主の聖地」と呼ばれている"},{"k":"life","zh":"中華民國把釣魚臺列嶼劃歸這裡的頭城鎮管轄","en":"The ROC places the disputed Diaoyutai (Senkaku) Islands under this county's Toucheng Township.","ja":"中華民国は尖閣諸島（釣魚台列嶼）をこの県の頭城鎮の管轄としている"},{"k":"life","zh":"本地閩南語腔調承襲漳州腔，最大特色是保留 /uinn/ 這個韻母","en":"The local Hokkien accent, inherited from Zhangzhou, is known for keeping the vowel sound /uinn/.","ja":"ここの閩南語のなまりは漳州系で、/uinn/という韻母を残すのが最大の特徴だ"},{"k":"legend","zh":"風水說法「龜蛇守海口」：外海的島像龜、河口沙丘像蛇，一同守住海口","en":"Feng shui lore says a turtle-shaped island and a snake-like sand dune guard the river mouth here.","ja":"風水では、亀の形の島と蛇のような砂丘が河口を守る「亀蛇守海口」と言われる"},{"k":"brand","zh":"員山鄉的金車酒廠所產威士忌，2015年獲選「世界最佳單一麥芽威士忌」","en":"A whisky from King Car's distillery in Yuanshan won World's Best Single Malt at the 2015 World Whiskies Awards.","ja":"員山郷の金車蒸留所のウイスキーが、2015年のワールド・ウイスキー・アワードで世界最高のシングルモルトに選ばれた"},{"k":"sport","zh":"東京奧運鞍馬銀牌李智凱出身羅東，因小時在菜市場表演體操被叫「菜市仔凱」","en":"Tokyo Olympic pommel horse silver medalist Lee Chih-kai is from here, nicknamed for doing gymnastics at a market.","ja":"東京五輪あん馬銀メダルの李智凱は羅東出身で、幼い頃市場で体操を披露し「市場の凱」と呼ばれた"},{"k":"sport","zh":"冬山河上舉辦國際名校划船邀請賽，2009年亞洲划船錦標賽也在這裡舉行","en":"The Dongshan River hosts an international collegiate regatta and hosted the 2009 Asian Rowing Championships.","ja":"冬山河では国際大学ボート招待レースが開かれ、2009年のアジアボート選手権もここで行われた"},{"k":"sport","zh":"頭城的蜜月灣與外澳是北臺灣著名的衝浪勝地","en":"Honeymoon Bay and Wai'ao in Toucheng are among northern Taiwan's best-known surfing spots.","ja":"頭城の蜜月湾や外澳は、台湾北部で有名なサーフィンスポットだ"},{"k":"food","zh":"除夕圍爐一定要吃「西魯肉」，是以白菜、蛋酥、肉絲勾芡的什錦羹","en":"New Year's Eve dinner here must include Xilu meat, a thick stew of cabbage, fried egg and pork shreds.","ja":"大晦日の団らんには、白菜と揚げ卵、豚肉のあんかけ「西魯肉」が欠かせない"},{"k":"food","zh":"炸豬肉條「卜肉」的「卜」，來自客家話「炸」的發音","en":"The name of bu-rou, a fried pork strip dish, comes from the Hakka word for deep-frying.","ja":"揚げ豚料理「卜肉」の「卜」は、客家語で「揚げる」の発音に由来する"},{"k":"festival","zh":"2000年起每年春天舉辦「綠色博覽會」，是童玩節之外的另一大活動","en":"Each spring since 2000 the county has held a Green Expo, its other big event besides the folk-game festival.","ja":"2000年から毎年春に「グリーン博覧会」が開かれ、童玩祭と並ぶ一大イベントになっている"},{"k":"nature","zh":"俗諺「竹風○雨」說新竹多風、這裡多雨，冬季東北季風的雨常綿延數月","en":"A proverb pairs windy Hsinchu with rainy here; winter rain from the northeast monsoon can last for months.","ja":"「竹風○雨」ということわざの通り新竹は風、ここは雨が多く、冬の季節風の雨は数か月続く"},{"k":"nature","zh":"三面環山、東面向海，平原的形狀像一個畚箕","en":"Mountains on three sides and the sea to the east give its plain the shape of a dustpan.","ja":"三方を山に囲まれ東は海に開け、平野はちり取りのような形をしている"}],
"TW-KEE":[{"k":"origin","zh":"舊稱「雞籠」，1875年設治時改成發音相近、字面較吉祥的現名","en":"Once called \"Kelang\" (Chicken Cage); in 1875 it was renamed with similar-sounding, more auspicious characters.","ja":"旧名は「鶏籠」。1875年、響きが近く縁起の良い字の現名に改められた"},{"k":"symbol","zh":"市鳥是黑鳶，也就是俗稱的「老鷹」","en":"Its official bird is the black kite, commonly called the \"eagle\" in Taiwan.","ja":"市の鳥はトビ（黒鳶）。台湾では俗に「老鷹」と呼ばれる"},{"k":"record","zh":"劉銘傳時代開鑿的獅球嶺隧道，是臺灣第一座鐵路隧道","en":"Shiqiuling Tunnel, dug under Liu Ming-chuan in the late 1880s, was Taiwan's first railway tunnel.","ja":"劉銘伝の時代に掘られた獅球嶺トンネルは、台湾初の鉄道トンネル"},{"k":"record","zh":"1926年啟用的西勢水庫，是臺灣第一座專供民生用水的水庫","en":"Xishi Reservoir, opened in 1926, was Taiwan's first reservoir built solely for household water.","ja":"1926年完成の西勢ダムは、台湾初の生活用水専用ダム"},{"k":"record","zh":"牛稠港溪是臺灣第一條人工運河","en":"Niuchougang Creek was Taiwan's first man-made canal.","ja":"牛稠港渓は台湾初の人工運河"},{"k":"record","zh":"境內砲臺的數量與密度都是全臺之冠","en":"It has more forts, and a higher density of them, than anywhere else in Taiwan.","ja":"砲台の数と密度はともに台湾一"},{"k":"work","zh":"臺語老歌〈港都夜雨〉的「港都」指的就是這裡，曲子是楊三郎在雨中寫成的","en":"The \"harbor city\" in the Taiwanese classic \"Rainy Night in the Harbor City\" is this place; Yang San-lang wrote the tune in its rain.","ja":"台湾語の名曲「港都夜雨」の「港都」はここ。楊三郎が雨の中で曲を書いた"},{"k":"people","zh":"臺灣五大家族之一的顏家在此發跡，靠採金、採煤被稱為「炭王金霸」","en":"The Yen family, one of Taiwan's Five Great Families, rose here through gold and coal mining: \"kings of coal and gold\".","ja":"台湾五大家族の一つ顔家はここで興り、金と石炭の採掘で「炭王金覇」と呼ばれた"},{"k":"history","zh":"1841年鴉片戰爭時，英艦砲擊這座港口、摧毀27門砲","en":"In 1841, during the First Opium War, a British warship bombarded the port and destroyed 27 cannon.","ja":"1841年のアヘン戦争中、英国艦がこの港を砲撃し、大砲27門を破壊した"},{"k":"history","zh":"1867年12月18日發生地震與海嘯，造成數百人罹難","en":"An earthquake and tsunami on 18 December 1867 killed hundreds of people here.","ja":"1867年12月18日に地震と津波が起き、数百人が犠牲になった"},{"k":"history","zh":"1668年鄭經的軍隊北上，把盤據這裡的荷蘭人趕走","en":"In 1668, Zheng Jing's forces drove the Dutch out of this port.","ja":"1668年、鄭経の軍が北上し、ここに拠っていたオランダ人を追い払った"},{"k":"history","zh":"1895年日軍從澳底登陸後，進入這座港市接收臺灣","en":"In 1895, Japanese troops landed at Aodi and then entered this port city to take over Taiwan.","ja":"1895年、日本軍は澳底に上陸した後、この港町に入って台湾を接収した"},{"k":"history","zh":"日治時期這裡是最接近日本本土的港口，成為日臺航線的發著港","en":"Under Japanese rule, as the port closest to Japan, it was the terminal for Japan-Taiwan ship routes.","ja":"日本統治時代は内地に最も近い港として、内台航路の発着港となり栄えた"},{"k":"record","zh":"日治時期縱貫鐵道（今西部幹線）的北端起點就在這裡","en":"Under Japanese rule, the northern end of the West Coast trunk railway was here.","ja":"日本統治時代、台湾縦貫鉄道（現在の西部幹線）の北の起点はここだった"},{"k":"record","zh":"國道一號中山高速公路的北端起點就在這裡","en":"The northern terminus of National Freeway 1, the Sun Yat-sen Freeway, is here.","ja":"国道1号・中山高速道路の北の起点はここにある"},{"k":"history","zh":"1923年裕仁皇太子訪臺時，搭乘的軍艦金剛號停泊在這裡的港外","en":"When Crown Prince Hirohito visited Taiwan in 1923, his warship Kongo anchored off this port.","ja":"1923年に裕仁皇太子が台湾を訪れた際、御召艦「金剛」はこの港の沖に停泊した"},{"k":"history","zh":"日治時期1899年起分期築港，港口從此能停泊萬噸級船舶","en":"From 1899 the Japanese rebuilt the harbor in phases, letting 10,000-ton ships berth.","ja":"1899年から日本が港を段階的に整備し、1万トン級の船が停泊できるようになった"},{"k":"record","zh":"1984年這裡的港口曾名列世界第七大貨櫃港","en":"In 1984, the port ranked as the world's seventh-largest container port.","ja":"1984年、この港はコンテナ取扱量で世界第7位を記録した"},{"k":"people","zh":"1997年擊敗西洋棋王的IBM電腦「深藍」，主要設計者許峰雄在這裡出生","en":"Feng-hsiung Hsu, chief designer of IBM's Deep Blue, which beat Kasparov in 1997, was born here.","ja":"1997年にチェス王者を破ったIBM「ディープ・ブルー」の主設計者、許峰雄はここの出身"},{"k":"brand","zh":"陽明海運總部設在七堵，前身可追溯到1873年的輪船招商局","en":"Yang Ming Marine is headquartered in Qidu; its roots trace to the 1873 China Merchants Steam Navigation Co.","ja":"陽明海運は七堵に本社を置き、その起源は1873年の輪船招商局にさかのぼる"},{"k":"food","zh":"崁仔頂漁市是臺灣具代表性的漁貨批發市場","en":"Kanzaiding Fish Market is one of Taiwan's best-known seafood wholesale markets.","ja":"崁仔頂漁市は、台湾を代表する水産物の卸売市場だ"},{"k":"festival","zh":"每年8月小管盛產時，這裡會舉辦鎖管季","en":"Every August, when small squid are in season, the city holds a squid festival.","ja":"毎年8月、小イカ（鎖管）の旬に合わせて「鎖管季」が開かれる"},{"k":"festival","zh":"元宵節的「炮獅」在西定路一帶遶境，最後在文化中心前舞獅","en":"At the Lantern Festival, 'Paoshi' lion dancers parade along Xiding Road and finish at the Cultural Center.","ja":"元宵節には獅子舞「炮獅」が西定路一帯を巡行し、最後に文化センター前で舞う"},{"k":"festival","zh":"和平島每年農曆六月十五前後舉行王爺「海上遊江」","en":"Around the 15th of the 6th lunar month, Heping Island holds a sea procession for the Wangye gods.","ja":"和平島では旧暦6月15日前後に、王爺の神々が海を巡る「海上遊江」が行われる"},{"k":"festival","zh":"這裡的中元祭源自1855年械鬥後的和解，以「鬥陣頭代替鬥人頭」","en":"The Ghost Festival here began in 1855 as a truce after deadly clan fights: compete with parades, not lives.","ja":"ここの中元祭は1855年の械闘後の和解から始まり、「人の首でなく陣頭で競う」とされた"},{"k":"life","zh":"市區道路以「忠、孝、仁、愛、信、義」開頭再加數字，例如忠一路、孝三路","en":"Downtown roads are named with virtues plus numbers, like Zhong 1st Road and Xiao 3rd Road.","ja":"市街地の道路は「忠・孝・仁・愛・信・義」に数字を付けた名で、忠一路や孝三路などがある"},{"k":"life","zh":"田寮河上的橋改建後以十二生肖命名，例如財鼠橋、福虎橋","en":"Bridges over the Tianliao River are named after the 12 zodiac animals, such as Wealth Rat Bridge.","ja":"田寮河に架かる橋は十二支にちなみ、「財鼠橋」「福虎橋」などと名付けられている"},{"k":"life","zh":"2018年，編號237164的小行星以這座城市命名","en":"In 2018, asteroid 237164 was named after this city.","ja":"2018年、小惑星237164番がこの市にちなんで命名された"},{"k":"nature","zh":"全市約95%是丘陵地，只有港區周邊有少量平地","en":"About 95% of the city is hilly, with flat land only around the harbor.","ja":"市域の約95%が丘陵地で、平地は港の周辺にわずかにあるだけだ"},{"k":"nature","zh":"彭佳嶼、棉花嶼、花瓶嶼這「北方三島」都歸這座城市管轄","en":"The northern islets of Pengjia, Mianhua and Huaping are administered by this city.","ja":"彭佳嶼・棉花嶼・花瓶嶼の「北方三島」は、この市の管轄だ"},{"k":"nature","zh":"仙洞巖的「仙洞聽濤」，是清代與日治時期地方八景之一","en":"'Listening to the Waves at Xiandong Cave' is one of the city's traditional Eight Scenic Views.","ja":"仙洞巌の「仙洞聴濤」は、清代と日本統治時代の地元八景の一つに数えられる"},{"k":"legend","zh":"傳說鱟群會在變天時爬上岸，港內曾有「鱟公嶼」「鱟母嶼」兩座礁岩","en":"Legend says horseshoe crabs crawled ashore before weather changes; two harbor reefs bore male and female crab names.","ja":"天気が変わる前にカブトガニが陸に上がると伝わり、港内にはかつて「鱟公嶼」「鱟母嶼」という岩礁があった"},{"k":"sport","zh":"每年6月會在外木山海域舉辦海上長泳","en":"Every June, an open-water long-distance swim is held off Waimushan.","ja":"毎年6月、外木山の海で遠泳大会が開かれる"},{"k":"origin","zh":"舊名一說是原住民凱達格蘭族族名的台語音譯","en":"One theory says the old name came from a transliteration of the Ketagalan people's name.","ja":"旧名は先住民ケタガラン族の族名がなまったものという説がある"},{"k":"symbol","zh":"市樹是楓香，市花則是紫薇與杜鵑兩種","en":"The city tree is the Formosan sweet gum; the city flowers are crepe myrtle and azalea.","ja":"市の木はフウ（楓香）、市の花はサルスベリとツツジだ"}],
"TW-KHH":[{"k":"origin","zh":"舊稱「打狗」，來自馬卡道族稱防海盜刺竹林的「Takau」，1920年改成日語音近的今名","en":"Once Takau, the Makatao word for a bamboo hedge against pirates; renamed in 1920 with a similar-sounding Japanese name.","ja":"旧名「打狗」は、マカタオ族が海賊よけの竹林を呼んだ「Takau」から。1920年に日本語で音の近い現名に"},{"k":"symbol","zh":"市鳥是綠繡眼，市樹是木棉","en":"Its city bird is the Swinhoe's white-eye; its tree is the kapok.","ja":"市の鳥はメジロ（緑繍眼）、市の木はキワタ（木棉）"},{"k":"sport","zh":"職棒台鋼雄鷹的主場在鳥松的澄清湖棒球場","en":"The CPBL's TSG Hawks play at Chengcing Lake Baseball Stadium in Niaosong.","ja":"プロ野球・台鋼ホークスの本拠地は鳥松の澄清湖野球場"},{"k":"record","zh":"遠在南海的東沙群島與南沙太平島，都歸這座城市管轄","en":"The Pratas Islands and Taiping Island in the South China Sea are both administered by this city.","ja":"南シナ海の東沙諸島と南沙の太平島は、どちらもこの市の管轄"},{"k":"record","zh":"1997年完工的85大樓曾是臺灣最高樓，2004年才被超越","en":"The 85 Sky Tower, finished in 1997, was Taiwan's tallest building until 2004.","ja":"1997年完成の85ビルは、2004年まで台湾一高いビルだった"},{"k":"record","zh":"阿公店水庫是臺灣唯一以防洪為主要目的的水庫","en":"Agongdian Reservoir is Taiwan's only reservoir built mainly for flood control.","ja":"阿公店ダムは台湾で唯一、洪水防止を主目的とするダム"},{"k":"festival","zh":"內門每年三月底到四月初舉辦宋江陣嘉年華","en":"Neimen holds a Song Jiang Battle Array carnival every late March or early April.","ja":"内門では毎年3月末～4月初めに宋江陣カーニバルが開かれる"},{"k":"life","zh":"內門很多居民從事辦桌，被稱為「總舖師之鄉」","en":"So many Neimen residents cater banquets that it's called the \"hometown of head chefs\".","ja":"内門は宴会料理人が多く「総舗師（宴席料理人）の里」と呼ばれる"},{"k":"origin","zh":"哈瑪星之名來自日語「浜線」，指通往港口的濱海鐵路","en":"Hamasen comes from the Japanese 'hama-sen', the seaside rail lines that served the port.","ja":"哈瑪星（ハマセン）の名は、港へ通じた臨港線「浜線」に由来する"},{"k":"record","zh":"捷運美麗島站的「光之穹頂」，號稱全球最大的單件玻璃藝術品","en":"The Dome of Light in Formosa Boulevard metro station is billed as the world's largest single glass artwork.","ja":"地下鉄美麗島駅の「光のドーム」は、世界最大の一体型ガラスアートとされる"},{"k":"record","zh":"衛武營是全球單一屋頂下最大的表演場館，原址是新兵訓練營","en":"Weiwuying, on a former army boot camp, is the world's largest performing arts venue under a single roof.","ja":"衛武営は新兵訓練所の跡地に建つ、単一屋根の下で世界最大の総合芸術劇場"},{"k":"brand","zh":"十大建設之一的中國鋼鐵，總部設在小港","en":"China Steel, one of the Ten Major Construction Projects, is headquartered in Xiaogang here.","ja":"十大建設の一つである中国鋼鉄は、小港に本社を置く"},{"k":"brand","zh":"1966年設立的加工出口區，號稱全球第一個加工出口區","en":"Its export processing zone, set up in 1966, is billed as the world's first.","ja":"1966年設立の加工輸出区は、世界初の加工輸出区とされる"},{"k":"nature","zh":"燕巢的烏山頂泥火山，是臺灣噴泥口最密集的地方","en":"Wushanding in Yanchao has Taiwan's densest cluster of mud volcano vents, protected as a nature reserve.","ja":"燕巣の烏山頂泥火山は、台湾で噴泥口が最も密集する場所"},{"k":"nature","zh":"旗津原是與本島相連的沙洲，1967年開闢第二港口後才變成島","en":"Cijin was a sandbar peninsula until a second harbor entrance cut it off into an island in 1967.","ja":"旗津は本島とつながる砂州だったが、1967年の第二港口開削で島になった"},{"k":"record","zh":"連接旗津與前鎮的過港隧道，是臺灣唯一的海底隧道","en":"The Cross-Harbor Tunnel linking Cijin and Qianzhen is Taiwan's only undersea tunnel.","ja":"旗津と前鎮を結ぶ過港トンネルは、台湾唯一の海底トンネル"},{"k":"legend","zh":"仙人賣的湯圓是山上的泥土做的，貪心的人吃掉半座山，成了半屏山","en":"Legend says greedy folk ate an immortal's dumplings made of mountain soil, leaving Banping Mountain half gone.","ja":"仙人が売った団子は山の土で、欲張りが食べ尽くして半屏山は半分になったという"},{"k":"legend","zh":"傳說海盜林道乾在壽山埋下十八籃半的金銀財寶","en":"Legend says the pirate Lin Daoqian buried eighteen and a half baskets of treasure on Shoushan.","ja":"海賊・林道乾が寿山に金銀十八籠半を埋めたという伝説がある"},{"k":"people","zh":"「倒在血泊裡的筆耕者」鍾理和在美濃務農寫作，紀念館也設在那裡","en":"Hakka writer Chung Li-ho farmed and wrote in Meinong, where his memorial hall now stands.","ja":"「血の海に倒れた筆耕者」鍾理和は美濃で農業と執筆を続け、記念館もそこにある"},{"k":"work","zh":"公視影集《痞子英雄》主要在這裡拍攝，劇中稱為「海港城」","en":"The TV series 'Black & White' was shot mainly here, a city the show calls 'Harbor City'.","ja":"ドラマ『痞子英雄』は主にここで撮影され、劇中では「海港城」と呼ばれる"},{"k":"festival","zh":"拉阿魯哇族的聖貝祭祭祀十二貝神，貝神平時封存在甕中","en":"The Hla'alua people's Sacred Shell Festival honors twelve shell spirits that are kept sealed in a jar.","ja":"ラアルア族の聖貝祭は、普段は壺に封じてある十二の貝神を祀る"},{"k":"history","zh":"1979年世界人權日的美麗島事件，就發生在今捷運美麗島站一帶","en":"The 1979 Formosa Incident on Human Rights Day took place around today's Formosa Boulevard station.","ja":"1979年の人権デーに起きた美麗島事件の現場は、今の地下鉄美麗島駅周辺"},{"k":"sport","zh":"羽球名將戴資穎出生在苓雅，三度奪得全英賽女單冠軍","en":"Badminton star Tai Tzu-ying was born in Lingya here and won three All England singles titles.","ja":"バドミントンの戴資穎は苓雅の生まれで、全英オープン女子シングルスを3度制した"},{"k":"record","zh":"左營的鳳山縣舊城，1722年築成時是臺灣第一座土城","en":"The old Fengshan county wall in Zuoying, built in 1722, was Taiwan's first earthen city wall.","ja":"左営の鳳山県旧城は、1722年に築かれた台湾初の土城"},{"k":"history","zh":"相傳在內門養鴨的朱一貴，1721年起事後十多天就攻下府城","en":"Zhu Yigui, said to be a duck farmer in Neimen, rose up in 1721 and took the capital in under two weeks.","ja":"内門でアヒルを飼っていたとされる朱一貴は1721年に蜂起し、十数日で府城を落とした"},{"k":"record","zh":"伊東豊雄設計的龍形國家體育場，號稱全球第一座太陽能供電的體育場","en":"Toyo Ito's dragon-shaped National Stadium is billed as the world's first stadium powered by solar energy.","ja":"伊東豊雄設計の龍形の国家体育場は、世界初の太陽光発電で電力をまかなう競技場とされる"},{"k":"history","zh":"1859年臺灣第一批天主教傳教士，從這裡的港口登陸","en":"Taiwan's first Catholic missionaries landed at this city's port in 1859.","ja":"1859年、台湾最初のカトリック宣教師がこの地の港から上陸した"},{"k":"history","zh":"這裡的港口1863年開埠，起初是安平港的外港","en":"This port opened to foreign trade in 1863, at first as an outer harbor of Anping.","ja":"この地の港は1863年、安平港の外港として開港した"},{"k":"history","zh":"2014年7月31日市區地下管線氣爆，造成32人死亡","en":"Underground gas pipeline explosions in the city on 31 July 2014 killed 32 people.","ja":"2014年7月31日、市街地の地下パイプライン爆発で32人が死亡した"},{"k":"origin","zh":"岡山舊稱「阿公店」，1920年改用與日本岡山相同的名字","en":"Gangshan, once called A-kong-tiam, was renamed in 1920 after Japan's Okayama.","ja":"岡山は旧称「阿公店」で、1920年に日本の岡山と同じ名に改められた"},{"k":"food","zh":"美濃人把粄條叫「面帕粄」，因為形狀像洗臉毛巾","en":"In Meinong, flat rice noodles are called 'face-towel ban' for their towel-like shape.","ja":"美濃では米麺の粄条を、顔拭きタオルに似た形から「面帕粄」と呼ぶ"},{"k":"life","zh":"俗話說「鳳林出校長，美濃出博士」","en":"A saying goes: 'Fenglin produces school principals, Meinong produces PhDs.'","ja":"「鳳林は校長を、美濃は博士を生む」という言い回しがある"},{"k":"life","zh":"岡山三寶是羊肉、蜂蜜與豆瓣醬，當地還是螺絲產業重鎮","en":"Gangshan's 'three treasures' are lamb, honey and bean paste, and it is also a hub of screw making.","ja":"岡山三宝は羊肉・蜂蜜・豆板醤で、ねじ産業の拠点でもある"}],
"TW-KIN":[{"k":"origin","zh":"明代取「固若○湯，雄鎮海○」之意命名，更早的舊名是「浯洲」","en":"It was named in the Ming dynasty from a phrase about an impregnable gate of the sea; its older name was Wuzhou.","ja":"明代に「固若○湯、雄鎮海○」の意味から命名。それ以前の旧名は「浯洲」"},{"k":"symbol","zh":"縣鳥是頭頂羽冠像扇子的戴勝","en":"Its county bird is the hoopoe, with its fan-like crest.","ja":"県の鳥は扇のような冠羽をもつヤツガシラ（戴勝）"},{"k":"people","zh":"新加坡歌手林俊傑的祖籍地","en":"Ancestral home of Singaporean singer JJ Lin.","ja":"シンガポールの歌手JJリン（林俊傑）の祖籍地"},{"k":"work","zh":"以軍中特約茶室為題材的電影《軍中樂園》的舞台","en":"Setting of Paradise in Service, a film about a military brothel.","ja":"軍の特約茶室を題材にした映画『軍中楽園』の舞台"},{"k":"record","zh":"道路密度是全國各縣市之冠","en":"It has the highest road density of any county or city in Taiwan.","ja":"道路密度は全国の県市で一番"},{"k":"life","zh":"路旁立著小心水獺的警示牌，瀕危的歐亞水獺在這裡出沒","en":"Roadside signs warn drivers of Eurasian otters, an endangered species living here.","ja":"道端に「カワウソ注意」の標識。絶滅危惧のユーラシアカワウソがすむ"},{"k":"life","zh":"居民持交通卡可以免費搭乘公車","en":"Residents ride the public buses for free with their transit card.","ja":"住民は交通カードで路線バスに無料で乗れる"},{"k":"festival","zh":"每年農曆四月十二舉行「迎城隍」遶境，相傳是紀念1680年的行政中心遷移","en":"Every 12th day of the 4th lunar month it holds the City God procession, said to mark the 1680 move of its seat.","ja":"毎年旧暦4月12日の「迎城隍」巡行は、1680年の役所移転を記念するとされる"},{"k":"history","zh":"唐朝803年在泉州設五個牧馬場，這座島就是其中之一","en":"In 803 the Tang set up five horse-breeding grounds around Quanzhou, and this island was one of them.","ja":"唐朝は803年に泉州に5つの牧馬場を設け、この島はその一つだった"},{"k":"legend","zh":"唐代帶人來此牧馬開墾的陳淵，被尊為守護神「開○恩主」","en":"Chen Yuan, who led Tang-era horse breeders here, is worshipped as the island's founding patron god.","ja":"唐代にここで牧馬を開いた陳淵は、守護神「開○恩主」として崇められている"},{"k":"history","zh":"1633年鄭芝龍在料羅灣海戰擊敗荷蘭艦隊","en":"In 1633 Zheng Zhilong defeated a Dutch fleet in the Battle of Liaoluo Bay off this island.","ja":"1633年、鄭芝龍は料羅湾の海戦でオランダ艦隊を破った"},{"k":"history","zh":"南明魯王朱以海1651年逃到這裡，1662年病逝島上","en":"The Ming loyalist Prince of Lu fled here in 1651 and died on the island in 1662.","ja":"南明の魯王朱以海は1651年にここへ逃れ、1662年に島で亡くなった"},{"k":"history","zh":"1664年清廷實施遷界，居民被迫內遷，全島一度荒無人煙","en":"Under the Qing coastal evacuation of 1664, residents were forced inland and the island was left empty.","ja":"1664年の清の遷界令で住民は内陸へ移され、島は一時無人になった"},{"k":"history","zh":"1949年福建省政府遷到這裡，使它一度成為福建省會","en":"In 1949 the Fujian provincial government moved here, briefly making it the provincial capital.","ja":"1949年に福建省政府が移り、一時は福建省の省都となった"},{"k":"origin","zh":"大二膽戰役後，蔣經國把「大二膽」改名為「大膽島」以鼓舞守軍","en":"After a 1950 battle, Chiang Ching-kuo renamed Da'erdan Island \"Dadan\" to boost the garrison's morale.","ja":"1950年の戦いの後、蒋経国は守備隊を励ますため「大二膽」を「大膽島」と改名した"},{"k":"life","zh":"八二三砲戰後解放軍改採「單打雙不打」，只在單日砲擊，持續到1979年","en":"After 1958 the PLA shelled the island only on odd-numbered days, a pattern that lasted until 1979.","ja":"八二三砲戦の後、人民解放軍は奇数日だけ砲撃する「単打双不打」を1979年まで続けた"},{"k":"life","zh":"馬山播音站曾以48支巨型喇叭向對岸心戰喊話，鄧麗君也曾在此播音","en":"Mashan Broadcasting Station once aimed 48 giant loudspeakers at China; Teresa Teng broadcast from here.","ja":"馬山放送所は48基の巨大スピーカーで対岸へ宣伝放送し、テレサ・テンもここで放送した"},{"k":"work","zh":"董振良1994年的電影《單打雙不打》，是第一部由在地導演拍攝的電影","en":"Dong Cheng-liang's 1994 film Every Odd Numbered Day was the first movie by a director from the island.","ja":"董振良の1994年の映画『單打雙不打』は、地元出身の監督による初めての映画だ"},{"k":"people","zh":"新加坡銀行家黃祖耀是祖籍在這裡的知名僑民","en":"Singapore banker Wee Cho Yaw is among the noted overseas Chinese with roots on this island.","ja":"シンガポールの銀行家・黄祖耀は、ここにルーツを持つ著名な華僑の一人だ"},{"k":"nature","zh":"這座島歷史上曾在1872、1892與1959年下過雪","en":"Snow has fallen on the island in 1872, 1892 and 1959.","ja":"この島では1872年、1892年、1959年に雪が降った記録がある"},{"k":"nature","zh":"年雨量約1,000公釐，蒸發量卻超過1,600公釐，島上呈半乾旱狀態","en":"Annual evaporation here exceeds rainfall, leaving the island semi-arid.","ja":"年間の蒸発量が降水量を上回り、島は半乾燥の状態にある"},{"k":"symbol","zh":"野生的藍孔雀是島上數量較多的大型野生動物","en":"Wild blue peafowl are among the more common large wild animals on the island.","ja":"野生のインドクジャクが、島に多い大型の野生動物の一つになっている"},{"k":"symbol","zh":"海岸棲息著被稱為活化石的鱟與文昌魚","en":"Its shores are home to \"living fossils\" such as horseshoe crabs and lancelets.","ja":"海岸には「生きた化石」のカブトガニやナメクジウオがすむ"},{"k":"brand","zh":"島上產鹽已有約一千一百年歷史，元朝就在此設有鹽場司","en":"Salt has been made here for about 1,100 years; the Yuan dynasty set up a salt office on the island.","ja":"島の製塩の歴史は約1100年に及び、元朝はここに塩場司を置いた"},{"k":"life","zh":"因未受日本統治，本地閩南語的「摩托車」不用日語借詞，而是照漢字念","en":"Never a Japanese colony, local Hokkien reads \"motorcycle\" from its Chinese characters, not a Japanese loanword.","ja":"日本統治を受けなかったため、ここの閩南語では「バイク」を日本語由来でなく漢字読みで言う"},{"k":"life","zh":"代管的烏坵鄉遠在莆田外海，居民說的是莆仙話","en":"Wuqiu, a far-off township it administers near Putian, speaks Puxian Min rather than Hokkien.","ja":"管轄する烏坵郷は遠く莆田の沖にあり、住民は莆仙語を話す"},{"k":"history","zh":"鄭成功在這裡大量造船，砍伐林木使島上植被銳減","en":"Koxinga's shipbuilding here caused heavy deforestation of the island.","ja":"鄭成功がここで大量に造船したため、島の森林が大きく失われた"},{"k":"record","zh":"連接大、小兩座主島的跨海大橋2022年通車，全長5.4公里","en":"A 5.4 km sea bridge linking the main island and Lieyu opened in 2022.","ja":"本島と烈嶼を結ぶ全長5.4キロの橋が2022年に開通した"},{"k":"life","zh":"2018年起，對岸晉江的水經海底管線送到這裡供應","en":"Since 2018, water from Jinjiang in Fujian has been piped to the island under the sea.","ja":"2018年から、対岸の晋江の水が海底パイプラインでここへ送られている"}],
"TW-LIE":[{"k":"symbol","zh":"縣花是紅花石蒜，縣樹是海桐","en":"Its county flower is the red spider lily; its tree is the Japanese cheesewood.","ja":"県の花はヒガンバナ（紅花石蒜）、県の木はトベラ（海桐）"},{"k":"record","zh":"面積與人口都是全國22個縣市中最少的","en":"It is the smallest of Taiwan's 22 counties and cities in both area and population.","ja":"面積も人口も全国22県市で最小"},{"k":"record","zh":"2021年成為全國第一個訂定光害管制條例的地方政府","en":"In 2021 it became Taiwan's first local government to pass a light-pollution ordinance.","ja":"2021年、全国で初めて光害規制条例を定めた自治体"},{"k":"origin","zh":"縣名沿用福建一個623年定名的古縣，海峽對岸至今也有同名的縣","en":"Its name comes from an old Fujian county named in 623; a county of the same name still exists across the strait.","ja":"県名は623年に定まった福建の古い県名を受け継ぐもので、対岸にも同名の県がある"},{"k":"festival","zh":"牛角村每年秋天舉行成年禮「做出幼」","en":"Niujiao village holds a coming-of-age rite called \"Zuo Chuyou\" every autumn.","ja":"牛角集落では毎年秋に成人儀礼「做出幼」が行われる"},{"k":"people","zh":"比利時修女石仁愛1975年來島上的幼稚園服務，居民都叫她「姆姆」","en":"Belgian nun Shih Jen-ai came to serve at an island kindergarten in 1975; locals call her \"Mumu\".","ja":"ベルギー人修道女・石仁愛は1975年から島の幼稚園で奉仕し、住民に「姆姆」と呼ばれる"},{"k":"work","zh":"電影《英勇戰士俏姑娘》以北竿芹壁村為故事發生地","en":"The film Like a Hero (Yingyong Zhanshi Qiao Guniang) is set in Qinbi village on Beigan.","ja":"映画『英勇戦士俏姑娘』（英題 Like a Hero）の舞台は北竿の芹壁村"},{"k":"life","zh":"依法規定，這裡的大眾運輸工具必須加播當地閩東語的廣播","en":"By law, public transport here must also make announcements in the local Eastern Min language.","ja":"法律で、ここの公共交通機関は地元の閩東語でも案内放送をしなければならない"},{"k":"history","zh":"二戰時這裡被親日的華人部隊佔領，日軍本身從未登島駐紮","en":"In WWII the islands were seized by a pro-Japanese Chinese force; Japanese troops themselves never occupied them.","ja":"第二次大戦中、ここは親日の中国人部隊に占領されたが、日本軍自体は駐留しなかった"},{"k":"history","zh":"明代鄭和船隊的船員曾在這些島上暫住","en":"Crewmen of Zheng He's Ming treasure fleet once stayed temporarily on these islands.","ja":"明代、鄭和の船団の船員がこの島々に一時滞在した"},{"k":"history","zh":"東莒的大埔石刻，記載明朝1617年沈有容在此生擒倭寇","en":"The Dapu Inscription on Dongju records how Ming general Shen Yourong captured Japanese pirates here in 1617.","ja":"東莒の大埔石刻は、1617年に明の沈有容がここで倭寇を生け捕りにした功績を刻む"},{"k":"history","zh":"東引長年由游擊隊改編而成的「反共救國軍」駐守","en":"Dongyin was long guarded by the Anti-Communist National Salvation Army, formed from guerrilla units.","ja":"東引は長年、ゲリラ部隊を改編した「反共救国軍」が守ってきた"},{"k":"history","zh":"2023年2月，連接臺灣的兩條海底電纜相繼被切斷","en":"In February 2023, both submarine cables linking the islands to Taiwan were cut.","ja":"2023年2月、台湾とを結ぶ2本の海底ケーブルが相次いで切断された"},{"k":"record","zh":"全縣只有4個鄉，是臺灣唯一沒有市也沒有鎮的縣","en":"It is the only county in Taiwan with no city or urban township, just four rural townships.","ja":"4つの郷だけからなり、市も鎮もない台湾唯一の県だ"},{"k":"festival","zh":"元宵「擺暝」在夜裡擺供品酬神，各村輪流舉辦，前後可長達一個月","en":"The Lantern Festival \"Bai Ming\" night offerings rotate among villages and can last a whole month.","ja":"元宵の「擺暝」は夜に供物を並べて神を祀る行事で、村ごとに日をずらし1か月続くこともある"},{"k":"festival","zh":"2022年首度舉辦國際藝術島「島嶼釀」","en":"In 2022 the islands held their first international island art festival.","ja":"2022年に初めて国際芸術祭「島嶼醸」が開かれた"},{"k":"brand","zh":"南竿的八八坑道以蔣中正88歲誕辰命名，戰地政務解除後改為酒廠窖藏","en":"Tunnel 88, named for Chiang Kai-shek's 88th birthday, became a distillery's liquor cellar after 1992.","ja":"八八坑道は蒋介石の88歳の誕生日にちなむ名で、1992年以降は酒造所の貯蔵庫になった"},{"k":"origin","zh":"莒光鄉1971年由白犬鄉改名，鄉名取自「毋忘在莒」","en":"Juguang Township was renamed from Baiquan in 1971 after the motto \"Do not forget Ju.\"","ja":"莒光郷は1971年に白犬郷から改名され、名は「毋忘在莒」にちなむ"},{"k":"origin","zh":"亮島原名「浪島」，1966年才改成今名","en":"Liang Island was originally called Lang Island and was renamed in 1966.","ja":"亮島の元の名は「浪島」で、1966年に改名された"},{"k":"origin","zh":"列島的通稱，來自南竿島因島上供奉海神的廟而得的別名","en":"The islands' common name comes from Nangan's nickname, taken from its temple to the sea goddess.","ja":"列島の通称は、海の女神を祀る廟にちなむ南竿島の別名から来ている"},{"k":"life","zh":"2003年曾考慮改縣名，以免與對岸同名的縣混淆","en":"In 2003 the county considered renaming itself to avoid confusion with its namesake across the strait.","ja":"2003年、対岸の同名の県と区別するため、県名の変更が検討された"},{"k":"legend","zh":"芹壁天后宮供奉的鐵甲元帥，其實是一位青蛙神","en":"The \"Iron Armor Marshal\" worshipped at Qinbi's temple is actually a frog god.","ja":"芹壁の天后宮に祀られる鉄甲元帥は、実は蛙の神様だ"},{"k":"legend","zh":"北竿后澳供奉的楊公八使，相傳與惡龍鬥法後漂流到此","en":"Yang Gong Bashi, worshipped at Hou'ao on Beigan, is said to have drifted here after battling an evil dragon.","ja":"北竿の后澳に祀られる楊公八使は、悪竜と戦った後ここへ流れ着いたと伝わる"},{"k":"legend","zh":"西莒的威武陳元帥是本地發展出的信仰，還分靈到浙江大陳島","en":"The Marshal Chen cult of Xiju began locally and even spread to Dachen Island in Zhejiang.","ja":"西莒の威武陳元帥は当地で生まれた信仰で、浙江の大陳島にも分霊された"},{"k":"life","zh":"到對岸黃岐半島的船程只要約20分鐘","en":"A ferry from here to China's Huangqi Peninsula takes only about 20 minutes.","ja":"対岸の黄岐半島までは船でわずか20分ほどだ"},{"k":"life","zh":"2012年舉行博弈公投，贊成設立賭場的一方勝出","en":"In a 2012 referendum, residents here voted in favor of allowing casinos.","ja":"2012年の住民投票で、カジノ設置への賛成が多数を占めた"},{"k":"life","zh":"島上說的閩東語，超過八成是長樂口音","en":"Over 80% of the locals who speak Eastern Min here use the Changle accent.","ja":"島で話される閩東語は、8割以上が長楽なまりだ"},{"k":"nature","zh":"列島南北綿延約54公里，由36個大小島礁組成","en":"The archipelago stretches about 54 km north to south and has 36 islands and islets.","ja":"列島は南北約54キロにわたり、大小36の島と岩礁からなる"},{"k":"symbol","zh":"周邊海域仍可見到偽虎鯨與露脊鼠海豚","en":"False killer whales and finless porpoises are still found in the surrounding waters.","ja":"周辺の海では、オキゴンドウやスナメリが今も見られる"}],
"TW-MIA":[{"k":"origin","zh":"名字源自道卡斯族「巴利社」（意為平原），客家人用音近的「貓貍」稱呼，後改雅字","en":"From the Taokas village Bari (\"plain\"); Hakka settlers wrote it as \"civet cat\", later swapped for elegant characters.","ja":"タオカス族の「バリ社」（平野の意）に由来。客家人が音の近い「猫貍」を当て、のち雅字に"},{"k":"symbol","zh":"縣花是桂花，縣鳥是喜鵲","en":"Its county flower is sweet osmanthus; its county bird is the magpie.","ja":"県の花はキンモクセイ（桂花）、県の鳥はカササギ"},{"k":"record","zh":"外海有臺灣第一座離岸風場「海洋風電」","en":"Taiwan's first offshore wind farm, Formosa 1, lies off its coast.","ja":"沖合に台湾初の洋上風力発電所「フォルモサ1」がある"},{"k":"life","zh":"全縣的外形很像一顆鑽石","en":"The county's outline looks a lot like a diamond.","ja":"県の形はダイヤモンドによく似ている"},{"k":"people","zh":"大河小說《寒夜》三部曲的作者李喬出生在大湖","en":"Li Qiao, author of the epic Wintry Night trilogy, was born in Dahu.","ja":"大河小説『寒夜』三部作の作者・李喬は大湖の生まれ"},{"k":"people","zh":"詩人詹冰出生在卓蘭，赴日學藥後回鄉開藥局，也當過理化老師","en":"Poet Zhan Bing was born in Zhuolan; he studied pharmacy in Japan, ran a drugstore at home and taught science.","ja":"詩人・詹氷は卓蘭生まれ。日本で薬学を学び帰郷して薬局を開き、理科教師も務めた"},{"k":"record","zh":"泰安鄉面積約614平方公里，大約占了全縣的三分之一","en":"Tai'an Township covers about 614 km², roughly a third of the county.","ja":"泰安郷は約614km²で、県全体の約3分の1を占める"},{"k":"life","zh":"造橋有一座專門介紹木炭的博物館","en":"Zaoqiao has a museum devoted entirely to charcoal.","ja":"造橋には木炭専門の博物館がある"},{"k":"history","zh":"1913年羅福星等人的抗日起事，因臨時法院設在這裡審判，被稱為「○○事件」","en":"The 1912–13 anti-Japanese plots led by Luo Fu-hsing were named after this county, where the special court sat.","ja":"1913年の羅福星らの抗日蜂起は、ここに臨時法院が置かれ裁かれたため「○○事件」と呼ばれる"},{"k":"history","zh":"1902年賽夏族頭目日阿拐不滿日本製腦業者奪地，起兵攻擊南庄支廳","en":"In 1902 a Saisiyat chief rose up at Nanzhuang against Japanese camphor firms that seized tribal land.","ja":"1902年、サイシャット族の頭目・日阿拐が樟脳業者の土地収奪に怒り、南庄支庁を襲撃した"},{"k":"history","zh":"1951年首屆民選縣長經過兩次選舉、五次投票才產生，是選舉史上的特例","en":"Its first elected county magistrate in 1951 took two elections and five rounds of voting to settle.","ja":"1951年の初の民選県長は、2回の選挙と5回の投票を経てようやく決まった"},{"k":"history","zh":"1895年乙未戰爭中，義軍在竹南的尖筆山與日軍激戰","en":"In 1895, resistance fighters battled invading Japanese troops on Jianbi Hill in Zhunan.","ja":"1895年の乙未戦争で、義勇軍が竹南の尖筆山で日本軍と激戦を交えた"},{"k":"people","zh":"臺灣民主國副總統、詩人丘逢甲，1864年出生在銅鑼","en":"Qiu Fengjia, poet and vice president of the 1895 Republic of Formosa, was born in Tongluo here in 1864.","ja":"1895年の台湾民主国の副総統で詩人の丘逢甲は、1864年に銅鑼で生まれた"},{"k":"people","zh":"寫實派作家、《人間》雜誌創辦人陳映真，1937年生於竹南","en":"Realist writer Chen Ying-chen, founder of Renjian magazine, was born in Zhunan in 1937.","ja":"リアリズム作家で雑誌『人間』を創刊した陳映真は、1937年に竹南で生まれた"},{"k":"work","zh":"以客語為主的電影《一八九五》，主角是出身銅鑼的抗日義軍領袖吳湯興","en":"The mostly Hakka-language film 1895 (2008) follows Wu Tang-hsing, a resistance leader born in Tongluo here.","ja":"客家語が中心の映画『一八九五』は、銅鑼出身の抗日義勇軍指導者・呉湯興が主人公"},{"k":"life","zh":"2016年起被網友戲稱為「○○國」，還成了脫口秀節目的主題","en":"Since 2016 netizens have jokingly called this county an independent 'nation', a meme even used on talk shows.","ja":"2016年頃からネットで「○○国」と冗談めかして呼ばれ、トーク番組の題材にもなった"},{"k":"record","zh":"頭份、三灣交界的永和山水庫，號稱臺灣第一座沒有水門的水庫","en":"Yonghe Mountain Reservoir is billed as Taiwan's first reservoir built without sluice gates.","ja":"頭份と三湾の境にある永和山ダムは、台湾初の水門のないダムとされる"},{"k":"symbol","zh":"2019年通過臺灣第一部保育單一物種的自治條例，保護的是石虎","en":"In 2019 it passed Taiwan's first local ordinance protecting a single species: the leopard cat.","ja":"2019年、台湾初の単一種を守る自治条例を制定。対象はベンガルヤマネコ（石虎）"},{"k":"festival","zh":"元宵節竹南中港也有「炸邯鄲爺」，用長竹竿綁鞭炮施放，作法和臺東不同","en":"At Lantern Festival, Zhunan's Zhonggang holds its own firecracker 'bombing' of Lord Handan, unlike Taitung's style.","ja":"元宵節には竹南の中港でも「炸邯鄲爺」があり、竹竿に爆竹を結んで鳴らす独特の方式"},{"k":"festival","zh":"竹南每年端午在中港溪出海口舉行「洗港」儀式，並有龍舟賽","en":"Every Dragon Boat Festival, Zhunan performs a 'harbor washing' rite at the mouth of the Zhonggang River.","ja":"竹南では毎年端午節に中港渓の河口で「洗港」の儀式と竜舟レースが行われる"},{"k":"festival","zh":"頭份義民廟每年農曆四月八日舉行斗燈節，有陣頭遊街與媽祖遶境","en":"Toufen's Yimin Temple holds a Dou Lamp festival around the 8th day of the 4th lunar month.","ja":"頭份の義民廟では毎年旧暦4月8日に斗灯節があり、陣頭の行列や媽祖巡行が行われる"},{"k":"origin","zh":"三義舊稱「三叉河」，因溪流匯成三叉狀，1953年嫌「叉」字不雅才改名","en":"Sanyi was once 'Three-Fork River' after a river junction; the 'fork' character was dropped as inelegant in 1953.","ja":"三義の旧称は川が三つ又に合流する「三叉河」で、1953年に「叉」が不雅として改名された"},{"k":"origin","zh":"卓蘭舊稱「罩蘭」，1920年居民嫌「罩」字上的「罒」會阻礙發展而去掉","en":"Zhuolan was once written 罩蘭; in 1920 locals dropped the top part of 罩, thinking it blocked progress.","ja":"卓蘭は旧称「罩蘭」。1920年、「罩」の上の「罒」が発展を妨げるとして取り除いた"},{"k":"origin","zh":"1751年客家墾民抓鬮分地，抽中第1號的地方就取名「頭份」","en":"In 1751 Hakka settlers drew lots for land; the plot drawn first was named Toufen, the 'first share'.","ja":"1751年、客家の開拓民がくじで土地を分け、1番を引いた土地が「頭份」と名付けられた"},{"k":"nature","zh":"海拔2,220公尺的加里山，被稱為○○的「母親山」","en":"Mount Jiali, 2,220 m high, is called the 'mother mountain' of this county.","ja":"標高2,220メートルの加里山は、○○の「母なる山」と呼ばれる"},{"k":"nature","zh":"獅潭鄉位在全縣正中央，是○○的地理中心","en":"Shitan Township sits in the middle of this county and is regarded as its geographic center.","ja":"獅潭郷は県のちょうど中央にあり、○○の地理的中心とされる"},{"k":"brand","zh":"1950、60年代南庄有20多家煤礦公司，礦工多達上萬人","en":"In the 1950s–60s Nanzhuang had over 20 coal companies employing some ten thousand miners.","ja":"1950〜60年代の南庄には20社以上の炭鉱会社があり、鉱夫は1万人に達した"},{"k":"brand","zh":"1960年代通霄的木雕外銷興盛，高速公路開通後師傅多轉往三義","en":"Tongxiao was a woodcarving export hub in the 1960s before its carvers moved to neighboring Sanyi.","ja":"1960年代は通霄が木彫輸出の中心だったが、高速道路開通後に職人の多くが三義へ移った"},{"k":"brand","zh":"竹南崎頂設有台灣菸酒的啤酒廠，是台灣啤酒北部主要供銷據點","en":"Qiding in Zhunan hosts a Taiwan Beer brewery, the brand's main supply base for northern Taiwan.","ja":"竹南の崎頂には台湾ビールの工場があり、北部の主要な供給拠点となっている"}],
"TW-NAN":[{"k":"origin","zh":"名字源自平埔族阿立昆族語「Ramtau」；清代以溪為界，溪北那一側叫「北投」","en":"From the Arikun word Ramtau; in Qing times the area across the river to the north was called \"Beitou\".","ja":"名は平埔族アリクン族の言葉「Ramtau」から。清代には川の北側が「北投」と呼ばれた"},{"k":"symbol","zh":"縣花是梅花，和中華民國的國花一樣","en":"Its county flower is the plum blossom, the same as the ROC's national flower.","ja":"県の花はウメで、中華民国の国花と同じ"},{"k":"sport","zh":"1983年起每年中秋前後舉辦萬人泳渡湖泊，2010年最年長的泳者99歲","en":"Since 1983 a mass swim across its famous lake is held around Mid-Autumn; in 2010 the oldest swimmer was 99.","ja":"1983年から毎年中秋の頃に湖の大遠泳。2010年の最高齢参加者は99歳"},{"k":"record","zh":"海拔3,275公尺的武嶺，是臺灣公路的最高點","en":"Wuling, at 3,275 m, is the highest point on Taiwan's road network.","ja":"標高3275mの武嶺は台湾の道路の最高地点"},{"k":"life","zh":"湖邊的九蛙疊像全部露出水面時，就代表到了枯水期、水位很低","en":"When all nine stacked frog statues by the lake show above water, the level is low in the dry season.","ja":"湖畔の「九蛙」像が全部水面から出ると、渇水期で水位が低い証拠"},{"k":"origin","zh":"縣內最有名的湖，據清代記載是因湖水「分丹、碧二色」而得名","en":"Its most famous lake was named, per a Qing record, for water \"divided into red and blue-green\".","ja":"県内で有名な湖の名は、清代の記録では水が「赤と碧の二色に分かれる」ことから"},{"k":"record","zh":"臺灣最長河流濁水溪的源頭在這裡","en":"The source of the Zhuoshui, Taiwan's longest river, is here.","ja":"台湾最長の川・濁水渓の源流がある"},{"k":"life","zh":"1934年水力發電工程完工後，最有名的湖從約4.55平方公里擴大到7.73平方公里","en":"A 1934 hydro project enlarged its famous lake from about 4.55 to 7.73 km².","ja":"1934年の水力発電工事で、有名な湖は約4.55km²から7.73km²に広がった"},{"k":"legend","zh":"相傳1855年林鳳池中舉返鄉，從福建帶回36株茶苗種在凍頂山","en":"Legend says Lin Fengchi brought 36 tea seedlings back from Fujian in 1855, starting Dongding tea.","ja":"1855年、科挙に合格した林鳳池が福建から茶苗36株を持ち帰り、凍頂山に植えたと伝わる"},{"k":"history","zh":"2001年8月8日，邵族獲政府正式承認為臺灣原住民族","en":"The Thao people were officially recognized as an Indigenous people of Taiwan on August 8, 2001.","ja":"2001年8月8日、サオ族は台湾の原住民族として正式に認定された"},{"k":"history","zh":"1814年郭百年等漢人入侵埔里，清廷隨後一度禁止漢人入墾","en":"In 1814 Han settlers led by Guo Bainian invaded Puli, and the Qing then banned Han settlement there.","ja":"1814年に郭百年らが埔里へ侵入し、清朝は一時漢人の入植を禁じた"},{"k":"history","zh":"1823年平埔族五族十四社遷入埔里，是當地史上最大的移民潮","en":"In 1823 plains peoples from 14 villages of five groups moved into Puli, its largest migration ever.","ja":"1823年、平埔族の5族14社が埔里へ移り住み、史上最大の移民の波となった"},{"k":"origin","zh":"草屯舊名「草鞋墩」，傳說是旅人在此換草鞋，1920年改為現名","en":"Caotun was once 'Straw Sandal Mound', said to be where travelers changed sandals; renamed in 1920.","ja":"草屯の旧名は「草鞋墩」。旅人がわらじを替えた所との伝説があり、1920年に改名"},{"k":"origin","zh":"國姓鄉的名字來自明鄭部將劉國軒屯兵開墾的「國姓埔」","en":"Guoxing Township is named for 'Koxinga's Field', where Koxinga's general Liu Guoxuan camped and farmed.","ja":"国姓郷の名は、鄭氏の部将・劉国軒が駐屯して開墾した「国姓埔」に由来する"},{"k":"origin","zh":"竹山舊稱「林圯埔」，紀念1668年在此遇襲身亡的明鄭參軍林圯","en":"Zhushan was once Linqipu, named for Lin Qi, a Ming-Zheng officer killed here in 1668.","ja":"竹山の旧称「林圯埔」は、1668年にここで襲われ戦死した鄭氏の参軍・林圯にちなむ"},{"k":"life","zh":"中興新村仿照英國新市鎮與花園城市規劃，辦公與住宅融入大片綠地","en":"Zhongxing New Village was planned on the British new-town and garden-city model, set among greenery.","ja":"中興新村はイギリスのニュータウンや田園都市をモデルに、緑の中に計画された"},{"k":"life","zh":"信義鄉戰後最初叫「羅娜鄉」，面積是全臺第二大的鄉","en":"Xinyi Township was first named Luona after WWII and is Taiwan's second-largest township by area.","ja":"信義郷は戦後当初「羅娜郷」と呼ばれ、面積は台湾で2番目に大きい郷"},{"k":"food","zh":"因滇緬軍民落腳，清境一帶發展出擺夷料理等雲南風味","en":"Thanks to settlers from the Yunnan–Burma border, Qingjing is known for Baiyi (Dai) cuisine.","ja":"雲南・ビルマから来た人々により、清境一帯ではタイ族（擺夷）料理が根付いた"},{"k":"food","zh":"日治時期集集香蕉據說曾供日本皇室食用，價格高達別處的十倍","en":"Jiji bananas were reportedly served to Japan's imperial household, selling for up to ten times others' price.","ja":"日本統治時代、集集のバナナは皇室に献上されたといわれ、他産地の10倍の値がついた"},{"k":"festival","zh":"清境的「奔羊節」會趕著羊群穿越公路，跑上約2公里","en":"At Qingjing's Running Sheep Festival, flocks are herded about 2 km across the highway.","ja":"清境の「奔羊節」では、羊の群れを約2キロ、道路を横切って追い立てる"},{"k":"festival","zh":"竹山社寮紫南宮每年春節舉行「發錢母」，元宵夜還有煙火秀","en":"Zhushan's Zinan Temple hands out 'mother money' at Lunar New Year and holds fireworks at Lantern Festival.","ja":"竹山の紫南宮では旧正月に縁起銭「銭母」を配り、元宵節の夜には花火も上がる"},{"k":"brand","zh":"水里蛇窯是臺灣仍完整運作的三座蛇窯中最古老的一座","en":"Shuili Snake Kiln is the oldest of Taiwan's three fully working 'snake' wood-fired kilns.","ja":"水里蛇窯は、台湾で今も稼働する三つの蛇窯のうち最も古い"},{"k":"brand","zh":"埔里手工紙源自日治時期的製紙所，2020年登錄為縣定文化資產","en":"Puli's handmade paper dates to a Japanese-era paper mill and became county cultural heritage in 2020.","ja":"埔里の手漉き紙は日本統治時代の製紙所に始まり、2020年に県の文化資産に登録された"},{"k":"record","zh":"水里蛇窯在2000年燒出的「千禧雙口瓶」，號稱全世界最高的陶器","en":"Shuili Snake Kiln's 2000 'Millennium Twin-Mouth Vase' is billed as the world's tallest piece of pottery.","ja":"水里蛇窯が2000年に焼いた「千禧双口瓶」は、世界一高い陶器とされる"},{"k":"record","zh":"集集1898年設立的樟腦出張所，是臺灣唯一現存的樟腦出張所","en":"Jiji's camphor branch office of 1898 is the only one of its kind still standing in Taiwan.","ja":"1898年設置の集集の樟脳出張所は、台湾で唯一現存する樟脳出張所"},{"k":"nature","zh":"集集的「綠色隧道」是1931年種下的樟樹林蔭道","en":"Jiji's 'Green Tunnel' is a road shaded by camphor trees planted in 1931.","ja":"集集の「緑のトンネル」は、1931年に植えられたクスノキの並木道"}],
"TW-NWT":[{"k":"people","zh":"中華民國第一位由人民直選的總統李登輝，出生在這裡的三芝","en":"Lee Teng-hui, the ROC's first directly elected president, was born in its Sanzhi district.","ja":"中華民国初の直接選挙による総統・李登輝は、ここの三芝で生まれた"},{"k":"sport","zh":"職棒富邦悍將的主場是這裡的新莊棒球場","en":"The CPBL's Fubon Guardians play their home games at Xinzhuang Baseball Stadium here.","ja":"プロ野球・富邦ガーディアンズの本拠地、新荘野球場がある"},{"k":"work","zh":"周杰倫自導自演的《不能說的秘密》在淡水的淡江中學拍攝，那正是他的母校","en":"Jay Chou's film Secret was shot at Tamkang High School in Tamsui, his own alma mater.","ja":"周杰倫監督・主演『言えない秘密』は淡水の淡江中学で撮影。そこは彼の母校だ"},{"k":"festival","zh":"元宵節壯丁扛著神轎跳進野柳漁港、游到對岸，稱為「神明淨港」","en":"On the Lantern Festival, men carry deity palanquins into Yehliu fishing harbor and swim them across: \"cleansing the harbor\".","ja":"元宵節に男たちが神輿を担いで野柳漁港に飛び込み、対岸まで泳ぐ「神明浄港」"},{"k":"record","zh":"八里的十三行遺址，是目前臺灣唯一確定擁有煉鐵技術的史前文化","en":"The Shihsanhang site in Bali is the only prehistoric culture in Taiwan confirmed to have smelted iron.","ja":"八里の十三行遺跡は、製鉄技術を持っていたと確認された台湾唯一の先史文化"},{"k":"life","zh":"金山的「蹦火仔」用電石點火引魚跳出水面，是全臺僅存的磺火捕魚","en":"Jinshan's \"fire fishing\" lights carbide torches so fish leap from the water, the last such fishery in Taiwan.","ja":"金山の「蹦火仔」はカーバイドの火で魚を跳ねさせる漁法で、台湾で唯一残る"},{"k":"origin","zh":"汐止舊名「水返腳」，相傳是基隆河漲潮時潮水到此折返","en":"Xizhi was once called 'Water-Return Foot', said to be where the Keelung River's tide turned back.","ja":"汐止の旧名「水返脚」は、基隆河の満潮がここで折り返すという言い伝えから"},{"k":"origin","zh":"升格直轄市時的新市名候選，還有「大河市」「富禮市」「環北市」等","en":"When it was upgraded in 2010, rejected name candidates included 'Dahe (Big River) City' and 'Fuli City'.","ja":"直轄市への昇格時、新しい市名の候補には「大河市」「富禮市」などもあった"},{"k":"history","zh":"1884年清法戰爭的滬尾之役，孫開華率清軍擊退登陸的法軍","en":"In the 1884 Battle of Tamsui, Qing troops under Sun Kaihua repelled a French landing.","ja":"1884年の清仏戦争・滬尾の戦いで、孫開華率いる清軍が上陸したフランス軍を撃退した"},{"k":"history","zh":"1858年天津條約後淡水開港，1890年代曾占全臺約六成貿易量","en":"Tamsui opened to foreign trade after 1858; by the 1890s it handled about 63% of Taiwan's trade.","ja":"1858年の天津条約後に淡水が開港し、1890年代には台湾の貿易の約6割を担った"},{"k":"history","zh":"1968年士林、北投、內湖、南港、木柵、景美從這裡劃出，併入隔壁的首都","en":"In 1968, Shilin, Beitou, Neihu, Nangang, Muzha and Jingmei were split off and merged into the neighboring capital.","ja":"1968年、士林・北投・内湖・南港・木柵・景美がここから切り離され、隣の首都に編入された"},{"k":"history","zh":"1950年宜蘭、羅東、蘇澳一帶從這裡分出，另成立宜蘭縣","en":"In 1950, the Yilan area was separated from this county to form Yilan County.","ja":"1950年、宜蘭・羅東・蘇澳一帯がここから分離して宜蘭県が成立した"},{"k":"record","zh":"八里的大坌坑遺址，是臺灣最早的新石器時代文化「大坌坑文化」的命名地","en":"Bali's Dapenkeng site gave its name to Taiwan's earliest Neolithic culture.","ja":"八里の大坌坑遺跡は、台湾最古の新石器文化「大坌坑文化」の名の由来となった"},{"k":"record","zh":"1914年創立的國立臺灣圖書館，是臺灣歷史最悠久的公共圖書館","en":"The National Taiwan Library, founded in 1914, is Taiwan's oldest public library.","ja":"1914年創立の国立台湾図書館は、台湾で最も歴史ある公共図書館だ"},{"k":"record","zh":"馬偕1880年在淡水創立的偕醫館，是北臺灣第一所西醫醫院","en":"The clinic George Mackay founded in Tamsui in 1880 was northern Taiwan's first Western hospital.","ja":"1880年にマッカイが淡水に開いた偕医館は、台湾北部初の西洋医学の病院だった"},{"k":"record","zh":"1884年設於淡水的女學堂，是臺灣第一所女子學校","en":"A girls' school founded in Tamsui in 1884 was Taiwan's first school for girls.","ja":"1884年に淡水に設立された女学堂は、台湾初の女子学校だった"},{"k":"people","zh":"1872年在淡水登岸的傳教士馬偕，一生替臺灣人拔了超過兩萬一千顆牙","en":"Missionary George Mackay, who landed at Tamsui in 1872, pulled over 21,000 teeth for Taiwanese in his life.","ja":"1872年に淡水に上陸した宣教師マッカイは、生涯で2万1千本以上の歯を抜いた"},{"k":"sport","zh":"萬金石馬拉松是臺灣第一場獲國際田總銀標認證的馬拉松","en":"The Wan Jin Shi Marathon was the first marathon in Taiwan to earn an IAAF Silver Label.","ja":"萬金石マラソンは、台湾で初めて国際陸連のシルバーラベルを得たマラソンだ"},{"k":"sport","zh":"2016年國際少年運動會在這裡舉行，是本市首度主辦的大型國際賽事","en":"The 2016 International Children's Games were the city's first major international sporting event.","ja":"2016年の国際児童競技大会は、この市が初めて主催した大規模な国際大会だった"},{"k":"work","zh":"侯孝賢電影《悲情城市》在九份拍攝，讓這座礦業山城受到矚目","en":"Hou Hsiao-hsien's A City of Sadness (1989) was filmed in Jiufen, drawing attention to the old mining town.","ja":"侯孝賢監督の映画『悲情城市』は九份で撮影され、この鉱山の町を一躍有名にした"},{"k":"festival","zh":"三峽祖師廟在農曆正月初六清水祖師誕辰時，會以神豬祭拜","en":"On the 6th day of the lunar new year, Sanxia's Zushi Temple marks Master Qingshui's birthday with sacrificial pigs.","ja":"三峡祖師廟では旧暦1月6日の清水祖師の誕生日に、神豚を供えて祝う"},{"k":"legend","zh":"清代志書記載，鶯歌石曾吐出迷霧困住鄭成功軍隊，被鄭軍斬斷頭部","en":"A Qing record says Yingge Rock breathed fog that trapped Koxinga's army, so his troops cut off its head.","ja":"清代の地誌によると、鶯歌石は霧を吐いて鄭成功の軍を惑わせ、首を斬られたという"},{"k":"legend","zh":"地方傳說觀音菩薩曾顯靈降服鶯歌石的鳥妖，那塊石頭供奉在妙善宮","en":"Local legend says Guanyin appeared to subdue the bird demon of Yingge Rock; the stone is enshrined at Miaoshan Temple.","ja":"観音菩薩が現れて鶯歌石の鳥の妖怪を鎮めたという伝説があり、その石は妙善宮に祀られる"},{"k":"food","zh":"永和豆漿起源於1955年中正橋頭的早餐店，由隨國府來臺的華北人創立","en":"Yonghe soy milk began in 1955 at shops near Zhongzheng Bridge, started by settlers from northern China.","ja":"永和豆漿は1955年、中正橋のたもとで華北出身の人々が始めた朝食店が起源だ"},{"k":"food","zh":"「萬里蟹」是本市替北海岸漁港捕撈的螃蟹打造的海產品牌","en":"'Wanli Crab' is the city's seafood brand for crabs landed at its north-coast fishing ports.","ja":"「萬里蟹」は、北海岸の漁港で水揚げされるカニを売り出す海産物ブランドだ"},{"k":"brand","zh":"替蘋果代工iPhone的鴻海（富士康）總部就設在這裡","en":"Foxconn, which assembles iPhones for Apple, is headquartered here.","ja":"AppleのiPhoneを受託生産する鴻海（フォックスコン）は、ここに本社を置く"},{"k":"brand","zh":"新莊的製鼓與三峽的染布，都是這裡傳承下來的傳統工藝","en":"Traditional crafts here include drum-making in Xinzhuang and cloth dyeing in Sanxia.","ja":"新荘の太鼓作りや三峡の染物は、ここに受け継がれる伝統工芸だ"},{"k":"nature","zh":"平溪的火燒寮是臺灣降雨最多的地方之一，年均雨量約3,700毫米","en":"Huoshaoliao in Pingxi is one of Taiwan's rainiest spots, averaging about 3,700 mm a year.","ja":"平渓の火焼寮は台湾有数の多雨地帯で、年平均雨量は約3,700ミリに達する"},{"k":"nature","zh":"國道五號雪山隧道約有三分之二位在坪林區境內","en":"About two-thirds of the Hsuehshan Tunnel on Freeway 5 lies within Pinglin District.","ja":"国道5号の雪山トンネルは、約3分の2が坪林区内にある"},{"k":"symbol","zh":"市鳥是鷺鷥，市樹是臺灣山櫻（鐘花櫻花）","en":"The city bird is the egret, and the city tree is the Taiwan cherry.","ja":"市の鳥はサギ（鷺鷥）、市の木はタイワンヒザクラ（台湾山桜）である"},{"k":"life","zh":"法鼓山的國際總本山在金山，世界宗教博物館則在永和","en":"Dharma Drum Mountain's headquarters is in Jinshan, and the Museum of World Religions is in Yonghe.","ja":"法鼓山の国際本部は金山に、世界宗教博物館は永和にある"},{"k":"life","zh":"汐止過去每逢颱風必淹，直到員山子分洪道完工才明顯改善","en":"Xizhi used to flood in nearly every typhoon until the Yuanshanzi flood diversion channel was finished.","ja":"汐止はかつて台風のたびに浸水したが、員山子分洪道の完成で大きく改善した"}],
"TW-PEN":[{"k":"origin","zh":"因為位在臺灣之西，古稱「西瀛」","en":"Lying west of Taiwan, it was anciently called Xiying.","ja":"台湾の西にあるため、古くは「西瀛」と呼ばれた"},{"k":"symbol","zh":"縣鳥是小雲雀","en":"Its county bird is the oriental skylark.","ja":"県の鳥はタイワンヒバリ（小雲雀）"},{"k":"people","zh":"歌手張雨生與潘安邦都出生在這裡的同一個眷村「篤行十村」","en":"Singers Chang Yu-sheng and Pan An-bang were both born in the same military village here, Duxing No. 10.","ja":"歌手の張雨生と潘安邦は、ここの同じ眷村「篤行十村」で生まれた"},{"k":"work","zh":"民歌〈外婆的○○灣〉是葉佳修根據潘安邦和外婆的真實故事寫的","en":"The folk song \"Grandma's ○○ Bay\" was written by Yeh Chia-hsiu from Pan An-bang's real story with his grandmother.","ja":"フォークソング「外婆的○○湾」は、葉佳修が潘安邦と祖母の実話をもとに作った"},{"k":"record","zh":"通樑古榕樹齡三百多年，一棵樹的氣根蔓延，覆蓋2000多平方公尺","en":"The Tongliang banyan, over 350 years old, is a single tree whose aerial roots cover more than 2,000 m².","ja":"通梁の古いガジュマルは樹齢300年超。一本の木の気根が2000㎡以上を覆う"},{"k":"record","zh":"漁民在外海撈起的「○○1號」下顎骨化石，可能屬於丹尼索瓦人","en":"A fossil jaw dredged up by fishermen offshore (\"○○ 1\") may belong to a Denisovan-related human.","ja":"漁師が沖で引き揚げた下顎骨化石「○○1」は、デニソワ人のものかもしれない"},{"k":"people","zh":"中法戰爭的法軍統帥孤拔，1885年在這裡的港內病逝","en":"French Admiral Courbet, commander in the Sino-French War, died of cholera aboard his flagship in its harbor in 1885.","ja":"清仏戦争の仏艦隊司令官クールベは、1885年ここの港内で病死した"},{"k":"life","zh":"為了保育海膽曾全面禁捕，2017年起只准捕直徑8公分以上的","en":"Sea urchin harvesting was banned in 2016; since 2017 only urchins over 8 cm across may be caught.","ja":"ウニ保護のため2016年に全面禁漁。2017年から直径8cm超のものだけ捕獲できる"},{"k":"origin","zh":"葡萄牙人稱這片群島為「漁夫群島」","en":"Portuguese sailors called this archipelago the \"Fishermen Islands.\"","ja":"ポルトガル人はこの群島を「漁師たちの島々」と呼んだ"},{"k":"history","zh":"1171年「毗舍耶」來襲，南宋因此派兵駐守這片群島","en":"After a 1171 raid by \"Bisheye\" raiders, the Song dynasty stationed soldiers on these islands.","ja":"1171年の「毘舎耶」の襲撃を受け、南宋はこの群島に兵を駐屯させた"},{"k":"history","zh":"元朝1281年在此設巡檢司，比臺灣本島納入版圖早了四百多年","en":"The Yuan set up a patrol office here in 1281, about 400 years before Taiwan itself was incorporated.","ja":"元朝は1281年にここへ巡検司を置き、台湾本島の編入より400年以上早かった"},{"k":"history","zh":"荷蘭人1622年在風櫃尾築城，兩年後被明軍逼退，建材拆去補強熱蘭遮城","en":"The Dutch built a fort at Fongguiwei in 1622; forced out two years later, they reused its materials for Fort Zeelandia.","ja":"オランダ人は1622年に風櫃尾に城を築いたが、2年後に明軍に追われ、資材をゼーランディア城に運んだ"},{"k":"history","zh":"1895年3月日軍先攻下這裡，比《馬關條約》割讓還早","en":"Japan seized these islands in March 1895, before the Treaty of Shimonoseki ceded them in April.","ja":"1895年3月、日本軍は下関条約での割譲より先にここを攻め落とした"},{"k":"history","zh":"二戰時馬公是日本海軍的重要基地，也是進攻菲律賓的出發地","en":"In WWII Makō was a major Japanese navy base and the launch point for the invasion of the Philippines.","ja":"第二次大戦中、馬公は日本海軍の重要基地で、フィリピン侵攻の出撃地だった"},{"k":"history","zh":"1970至80年代，在海上獲救的越南難民被送到這裡安置","en":"Vietnamese boat people rescued at sea in the 1970s and 1980s were sent to these islands.","ja":"1970〜80年代、海で救助されたベトナム難民がここに送られた"},{"k":"life","zh":"2009年舉行設立賭場的博弈公投，反對票多於贊成票而未通過","en":"A 2009 referendum on allowing casinos here was voted down.","ja":"2009年、カジノ設置の是非を問う住民投票が行われ、否決された"},{"k":"people","zh":"清代蔡廷蘭是這裡唯一的進士，人稱「開○進士」","en":"Cai Tinglan was the only jinshi (top imperial scholar) ever produced here in the Qing era.","ja":"清代の蔡廷蘭はここ唯一の進士で、「開○進士」と呼ばれた"},{"k":"people","zh":"本地進士蔡廷蘭1836年遇颱風漂到越南，把見聞寫成《海南雜著》","en":"Blown to Vietnam by a typhoon in 1836, local scholar Cai Tinglan wrote a famous travelogue about it.","ja":"地元出身の蔡廷蘭は1836年に台風で越南へ漂着し、その見聞を『海南雑著』に記した"},{"k":"legend","zh":"虎井嶼東側海底有像城牆的構造，傳說是一座沉沒的古城","en":"Underwater wall-like structures off Hujing Island are said to be the ruins of a sunken ancient city.","ja":"虎井嶼の東の海底には城壁のような構造があり、沈んだ古城の伝説がある"},{"k":"origin","zh":"虎井嶼的名字來自島形像一隻蹲伏的老虎","en":"Hujing Island is named for its shape, like a crouching tiger with a harbor cutting into it.","ja":"虎井嶼の名は、島の形がうずくまる虎に似ていることに由来する"},{"k":"origin","zh":"吉貝嶼因島形像漂在海上的螺貝，原稱「嘉貝嶼」","en":"Jibei Island was first called Jiabei because it looks like a seashell floating on the sea.","ja":"吉貝嶼は海に浮かぶ巻貝のような形から、もとは「嘉貝嶼」と呼ばれた"},{"k":"record","zh":"群島上的石滬有570處以上，光是吉貝嶼就超過一百處","en":"The islands have over 570 stone fish weirs, more than 100 of them around Jibei Island alone.","ja":"群島には石積みの魚垣「石滬」が570以上あり、吉貝嶼だけで100を超える"},{"k":"life","zh":"冬季季風夾帶「鹹雨」，農民用玄武岩、珊瑚石砌牆圍出「菜宅」種菜","en":"Farmers grow vegetables inside basalt and coral stone walls that shield crops from salty winter winds.","ja":"冬の季節風が「塩雨」を運ぶため、農民は玄武岩やサンゴ石の壁で囲った「菜宅」で野菜を育てる"},{"k":"nature","zh":"群島上沒有任何河川，雨量也只有臺灣本島的一半左右","en":"There are no rivers on these islands, and rainfall is only about half that of Taiwan's main island.","ja":"群島には川が一本もなく、雨量も台湾本島の半分ほどしかない"},{"k":"nature","zh":"全縣最高點在大貓嶼，海拔只有70公尺","en":"The county's highest point, on Damao Islet, is only 70 m above sea level.","ja":"県の最高地点は大猫嶼にあり、標高わずか70メートルだ"},{"k":"nature","zh":"這片群島是中新世一座盾狀火山的殘跡","en":"The islands are the remnants of a Miocene shield volcano.","ja":"この群島は、中新世の盾状火山の名残だ"},{"k":"symbol","zh":"除了縣花、縣鳥，這裡還有「縣魚」：玳瑁石斑魚","en":"Besides a county bird and flower, it even has an official county fish, a species of grouper.","ja":"県花や県鳥のほかに「県魚」もあり、玳瑁石斑というハタの一種が選ばれている"},{"k":"life","zh":"1953年「○○漁火」入選臺灣八景，夜裡漁火與星光相映","en":"In 1953 the islands' night fishing lights were chosen as one of the Eight Views of Taiwan.","ja":"1953年、夜の漁火が「台湾八景」の一つに選ばれた"},{"k":"life","zh":"明清時期的移民中，祖籍金門的占了一半以上","en":"Over half of the Ming and Qing era settlers here traced their roots to Kinmen.","ja":"明清時代の移民の半数以上は、祖籍が金門だった"},{"k":"record","zh":"2011年被寂寞星球選為全球十大最佳世外桃源島嶼之一","en":"In 2011 Lonely Planet named the archipelago one of the world's top 10 secret islands.","ja":"2011年、ロンリープラネットで世界の秘境の島トップ10に選ばれた"},{"k":"record","zh":"是「世界最美麗海灣俱樂部」的會員","en":"It is a member of the Most Beautiful Bays in the World Club.","ja":"「世界で最も美しい湾クラブ」に加盟している"}],
"TW-PIF":[{"k":"symbol","zh":"縣鳥是紅尾伯勞，縣樹是椰子樹","en":"Its county bird is the brown shrike; its tree is the coconut palm.","ja":"県の鳥はアカモズ（紅尾伯労）、県の木はココヤシ"},{"k":"origin","zh":"舊稱「阿猴」，1920年以當地一座書院的名字改成現名","en":"Once called A-kâu; in 1920 it was renamed after a local academy.","ja":"旧名は「阿猴」。1920年、地元の書院の名にちなんで現名に"},{"k":"record","zh":"萬金聖母聖殿是臺灣現存最古老的教堂建築","en":"Wanjin Basilica is the oldest surviving church building in Taiwan.","ja":"万金聖母聖殿は台湾に現存する最古の教会建築"},{"k":"record","zh":"臺灣本島周邊的最南端七星岩屬於這裡","en":"Qixingyan reef, the southernmost point around Taiwan's main island, belongs here.","ja":"台湾本島周辺の最南端・七星岩はここに属する"},{"k":"work","zh":"電影《海角七號》以恆春為舞台，曾是臺灣影史國片票房冠軍","en":"Cape No. 7 is set in Hengchun; it was long the top-grossing Taiwanese film.","ja":"映画『海角七号』の舞台は恒春。長く台湾映画の興行収入1位だった"},{"k":"people","zh":"兩度奪得奧斯卡最佳導演的李安，出生在潮州","en":"Ang Lee, two-time Oscar winner for Best Director, was born in Chaozhou here.","ja":"アカデミー監督賞を2度受賞したアン・リーは潮州の生まれ"},{"k":"festival","zh":"臺灣歷史最悠久的大型音樂祭「春天吶喊」，1995年起在墾丁舉辦","en":"Spring Scream, Taiwan's longest-running big music festival, began in Kenting in 1995.","ja":"台湾で最も歴史ある大型音楽祭「春天吶喊」は、1995年から墾丁で開かれた"},{"k":"life","zh":"冬季強勁的「落山風」把洋蔥葉子吹倒，養分集中到球莖，洋蔥變得更甜","en":"Strong winter \"downslope winds\" flatten onion leaves, sending nutrients to the bulb and making them sweeter.","ja":"冬の強い「落山風」が玉ねぎの葉を倒し、養分が球に集まって甘くなる"},{"k":"history","zh":"1867年美國商船羅發號在恆春外海觸礁，上岸船員遭原住民殺害","en":"In 1867 the US ship Rover wrecked off Hengchun, and its crew were killed by local indigenous people.","ja":"1867年、米商船ローバー号が恒春沖で座礁し、上陸した船員が先住民に殺害された"},{"k":"people","zh":"瑯嶠十八社總頭目卓杞篤與美國領事約定：遇難船員舉紅旗求援","en":"Paiwan chief Tauketok agreed with a US consul that shipwrecked sailors could seek help by raising a red flag.","ja":"瑯嶠十八社の総頭目トケトクは米領事と、遭難者は赤旗を掲げて助けを求めると約した"},{"k":"work","zh":"公視影集《斯卡羅》改編自陳耀昌小說《傀儡花》，重現1867年的瑯嶠","en":"The PTS drama 'Seqalu: Formosa 1867', based on Chen Yao-chang's novel, recreates Langqiao in 1867.","ja":"公視（台湾公共テレビ）のドラマ『斯卡羅』は陳耀昌の小説『傀儡花』が原作で、1867年の瑯嶠を描く"},{"k":"festival","zh":"排灣族五年祭在來義古樓等部落舉行，勇士用長竿刺藤球","en":"The Paiwan five-year festival, held in villages such as Kuljaljau in Laiyi, has warriors spearing rattan balls.","ja":"パイワン族の五年祭は来義の古楼などで行われ、勇士が長い竿で籐の球を突く"},{"k":"festival","zh":"馬卡道族每年在加蚋埔公廨舉行夜祭","en":"The Makatao people hold an annual night festival at the Kalapu ancestral house.","ja":"マカタオ族は毎年、加蚋埔の公廨で夜祭を行う"},{"k":"origin","zh":"沈葆楨因當地氣候溫暖、四季如春，把瑯嶠改名為恆春","en":"Qing official Shen Baozhen renamed Langqiao 'Hengchun', meaning eternal spring, for its warm climate.","ja":"沈葆楨は一年中春のように暖かいことから、瑯嶠を「恒春」と改めた"},{"k":"history","zh":"1874年牡丹社事件後，清廷在半島南端設立恆春縣","en":"After the 1874 Mudan Incident, the Qing set up Hengchun County at the southern tip of the peninsula.","ja":"1874年の牡丹社事件の後、清は半島南端に恒春県を置いた"},{"k":"record","zh":"恆春古城是臺灣目前保存最完整的古代城池","en":"Hengchun's walled old town is the most completely preserved historic walled city in Taiwan.","ja":"恒春古城は、台湾で最も完全な形で残る古い城郭"},{"k":"nature","zh":"恆春東門外的「出火」，地下天然氣冒出地面，點火就會燃燒","en":"At Chuhuo outside Hengchun's east gate, natural gas seeps from the ground and burns once lit.","ja":"恒春東門外の「出火」では、地中の天然ガスが噴き出し、火をつけると燃える"},{"k":"symbol","zh":"南仁湖的黃灰澤蟹是臺灣特有種，繁殖時不必到海邊","en":"The Taiwan-endemic freshwater crab of Nanren Lake breeds without ever going to the sea.","ja":"南仁湖にすむ台湾固有のサワガニ「黄灰澤蟹」は、海に行かずに繁殖する"},{"k":"nature","zh":"這裡是臺灣本島唯一擁有熱帶林相的地區","en":"It is the only part of Taiwan's main island with tropical forest.","ja":"台湾本島で唯一、熱帯林の植生を持つ地域"},{"k":"history","zh":"1721年朱一貴事件時，客家庄組成民團抵抗，六堆忠義祠就是紀念他們","en":"In 1721 Hakka villages formed militias against Zhu Yigui's rebels; the Liudui Loyalty Shrine honors them.","ja":"1721年の朱一貴事件で客家の村々は民兵を組んで抵抗し、六堆忠義祠が彼らを祀る"},{"k":"sport","zh":"內埔美和中學青少棒隊奪得11座世界冠軍，有「南美和、北華興」之稱","en":"Meiho Junior High in Neipu won 11 world junior baseball titles: 'Meiho in the south, Hua Hsing in the north.'","ja":"内埔の美和中学の野球チームは世界一に11度輝き、「南の美和、北の華興」と並び称された"},{"k":"brand","zh":"恆春南灣的核三廠，是唯一位在南臺灣的核能電廠","en":"The Third Nuclear Power Plant at Nanwan, Hengchun, is the only nuclear power plant in southern Taiwan.","ja":"恒春・南湾の第三原子力発電所は、南台湾で唯一の原子力発電所"},{"k":"nature","zh":"北大武山是排灣族的聖山，也是臺灣百岳中最南端的一座","en":"North Dawu Mountain, sacred to the Paiwan, is the southernmost of Taiwan's Top 100 Peaks.","ja":"北大武山はパイワン族の聖山で、台湾百岳の最南端の山"},{"k":"food","zh":"萬丹有「紅豆的故鄉」之稱，也是臺灣四大酪農區之一","en":"Wandan is called the 'home of red beans' and is one of Taiwan's four main dairy-farming areas.","ja":"万丹は「小豆の故郷」と呼ばれ、台湾四大酪農地帯の一つでもある"},{"k":"life","zh":"境內有八個山地鄉，是全臺山地鄉最多的縣市","en":"With eight mountain indigenous townships, this county has more than any other in Taiwan.","ja":"山地郷が8つあり、台湾の県市で最も多い"},{"k":"food","zh":"港口茶是「恆春三寶」之一，另外兩寶是瓊麻和洋蔥","en":"Gangkou tea is one of Hengchun's 'three treasures', along with sisal and onions.","ja":"港口茶は「恒春三宝」の一つで、ほかの二つはサイザル麻と玉ねぎ"},{"k":"people","zh":"客家作家鍾理和1915年出生在今高樹鄉廣興村","en":"Hakka writer Chung Li-ho was born in 1915 in today's Guangxing Village, Gaoshu Township.","ja":"客家の作家・鍾理和は1915年、現在の高樹郷広興村で生まれた"}],
"TW-TAO":[{"k":"origin","zh":"清代原名「虎茅庄」，因茅草叢生容易傷人；後來移民遍植果樹才改名","en":"Originally \"Humao Village\" for its thick, cutting thatch grass; it was renamed after settlers planted fruit trees.","ja":"旧名は「虎茅庄」。茅が茂って人を傷つけたため。のちに移民が果樹を植え改名"},{"k":"sport","zh":"日本樂天集團經營的職棒球隊，主場就在這裡的中壢","en":"The CPBL team owned by Japan's Rakuten plays its home games in Zhongli here.","ja":"楽天グループのプロ野球チームが、ここの中壢を本拠地にしている"},{"k":"life","zh":"外籍移工人數全臺最多，約13萬人","en":"It has more migrant workers than any other Taiwanese city or county: about 130,000.","ja":"外国人労働者の数は台湾最多で、約13万人"},{"k":"record","zh":"眷村數量全臺之冠，全盛時期約86處；2001年也率先舉辦眷村文化節","en":"It had more military dependents' villages than anywhere in Taiwan, about 86 at its peak, and held the first such festival in 2001.","ja":"眷村（軍人家族村）の数は台湾最多で最盛期約86か所。2001年に初の眷村文化祭を開催"},{"k":"record","zh":"大溪木藝生態博物館是臺灣第一座「無圍牆博物館」","en":"Daxi Wood Art Ecomuseum is Taiwan's first \"museum without walls\".","ja":"大渓木芸エコミュージアムは台湾初の「壁のない博物館」"},{"k":"festival","zh":"每年農曆六月廿四關公生日，大溪普濟堂遶境走遍全區，已登錄為文化資產","en":"On the 24th of the 6th lunar month, Daxi's Puji Temple parades across the district for Guan Gong's birthday, a listed folk heritage.","ja":"毎年旧暦6月24日、大渓・普済堂の関帝誕生祭の巡行が全区を回る。文化財に登録"},{"k":"life","zh":"唯一沒有任何銀行總行設立的直轄市","en":"It is the only special municipality with no bank headquartered in it.","ja":"銀行の本店が一つもない唯一の直轄市"},{"k":"people","zh":"「帽子歌后」鳳飛飛的故鄉","en":"Hometown of Fong Fei-fei, pop's \"Queen of Hats\".","ja":"「帽子の歌姫」鳳飛飛（フォン・フェイフェイ）の故郷"},{"k":"origin","zh":"大溪舊名「大姑陷」，源自平埔族霄裡社對大漢溪的稱呼，1920年改今名","en":"Daxi was once 'Dakoham', from a Plains Indigenous name for the Dahan River; it was renamed in 1920.","ja":"大渓の旧名「大姑陥」は平埔族霄裡社による大漢渓の呼び名に由来し、1920年に改名された"},{"k":"history","zh":"明鄭時期在南崁港設立據點，是北臺灣出入的重要門戶","en":"Under the Zheng regime, Nankan port was set up as a key gateway to northern Taiwan.","ja":"鄭氏政権の時代、南崁港に拠点が置かれ、台湾北部の重要な玄関口となった"},{"k":"history","zh":"1803年林本源家族因漳泉械鬥遷居大溪，開圳並經營米鹽河運","en":"In 1803 the Lin Ben Yuan family moved to Daxi after clan fighting and built canals and river trade.","ja":"1803年、林本源家は漳泉械闘を避けて大渓に移り、水路を開き米と塩の水運を営んだ"},{"k":"history","zh":"1890年北路磺腦局設立後，大溪成為茶葉、樟腦與木材的集散地","en":"After a sulfur-and-camphor bureau opened in 1890, Daxi became a hub for tea, camphor and timber.","ja":"1890年に北路磺脳局が置かれると、大渓は茶・樟脳・木材の集散地となった"},{"k":"history","zh":"日治時期1924年竣工的大圳，是這裡重要的灌溉水利工程","en":"A major irrigation canal completed here in 1924 was a key water project of the Japanese era.","ja":"1924年に完成した大圳は、日本統治時代のこの地の重要な灌漑工事だった"},{"k":"history","zh":"1950年才從新竹縣分出，獨立成縣","en":"It was split off from Hsinchu County and became a county of its own in 1950.","ja":"1950年に新竹県から分かれ、独立した県となった"},{"k":"history","zh":"美國無線電公司（RCA）工廠的污染案，是臺灣著名的工業公害事件","en":"Pollution from the RCA factory here became one of Taiwan's best-known industrial contamination cases.","ja":"米RCA社の工場による汚染事件は、台湾で有名な産業公害事件の一つだ"},{"k":"brand","zh":"1989年在八德開幕的萬客隆，被稱為國內量販店的始祖","en":"Makro's Bade store, opened in 1989, is called the forerunner of hypermarkets in Taiwan.","ja":"1989年に八徳で開業したマクロは、台湾の量販店の元祖とされる"},{"k":"brand","zh":"長榮航空與中華航空的總部都設在這裡","en":"Both EVA Air and China Airlines are headquartered here.","ja":"エバー航空とチャイナエアラインは、どちらもここに本社を置いている"},{"k":"life","zh":"國家中山科學研究院設在龍潭，是國內最重要的軍事科研機構之一","en":"The National Chung-Shan Institute of Science and Technology, a key military research body, is in Longtan.","ja":"国家中山科学研究院は龍潭にあり、台湾有数の軍事研究機関だ"},{"k":"brand","zh":"大溪是傳統家具重鎮，有「木器之鄉」之稱，紅木神桌雕紋最出名","en":"Daxi is called the 'home of woodcraft', famous for its carved rosewood altar tables.","ja":"大渓は「木器の里」と呼ばれ、紅木の神卓の彫刻が特に有名だ"},{"k":"festival","zh":"大溪擁有上百尊神將（大仙尪），因此有「神將窟」的美名","en":"Daxi has over a hundred giant deity puppets, earning it the nickname 'Den of Divine Generals'.","ja":"大渓には神将（大きな神像人形）が百体以上あり、「神将窟」と呼ばれる"},{"k":"people","zh":"「臺灣歌謠之父」鄧雨賢生於今平鎮與龍潭交界，作有〈望春風〉〈雨夜花〉","en":"Teng Yu-hsien, called the father of Taiwanese popular song, was born here in 1906.","ja":"「台湾歌謡の父」鄧雨賢は1906年にここで生まれ、「望春風」「雨夜花」を作曲した"},{"k":"sport","zh":"女子高爾夫名將曾雅妮的出生地就在這裡","en":"Golfer Yani Tseng was born here.","ja":"女子ゴルフのスター、曽雅妮（ヤニ・ツェン）はここの出身だ"},{"k":"sport","zh":"2011年臺灣第一項LPGA賽事在楊梅的揚昇高爾夫球場舉行","en":"Taiwan's first LPGA tournament was held at Sunrise Golf Club in Yangmei in 2011.","ja":"2011年、台湾初のLPGAツアー大会が楊梅の揚昇ゴルフ場で開かれた"},{"k":"sport","zh":"1993年完工的巨蛋體育館，屋頂結構參考了自行車輪的設計","en":"The city's dome arena, built in 1993, has a roof structure modeled on bicycle wheels.","ja":"1993年完成のドーム体育館は、自転車の車輪を参考にした屋根構造を持つ"},{"k":"record","zh":"龍潭聖蹟亭是全臺面積最大、規畫最完整的惜字亭","en":"Longtan's Shengji Pavilion is Taiwan's largest and most complete pavilion for burning written paper.","ja":"龍潭の聖蹟亭は、文字を書いた紙を焼く惜字亭として台湾最大で最も完全なものだ"},{"k":"record","zh":"市內的忠烈祠原是日治時期的神社，被譽為日本境外保存最完整的神社之一","en":"The Martyrs' Shrine here, a former Shinto shrine, is one of the best-kept shrines outside Japan.","ja":"ここの忠烈祠は元は日本統治時代の神社で、日本国外で最も保存状態の良い神社の一つとされる"},{"k":"symbol","zh":"楊梅的人工埤塘是台北赤蛙的棲地，2012年公告為首座埤塘保護區","en":"A man-made pond in Yangmei shelters the Taipei frog and became the city's first pond reserve in 2012.","ja":"楊梅の人工ため池はタイペイアカガエルの生息地で、2012年に初のため池保護区となった"},{"k":"nature","zh":"最高峰是海拔2,444公尺的雪白山","en":"The highest peak is Mount Xuebai, at 2,444 meters.","ja":"市内の最高峰は、標高2,444メートルの雪白山である"},{"k":"nature","zh":"大漢溪斜穿市境，把全市分成東南與西北兩大部分","en":"The Dahan River cuts across the city, dividing it into southeast and northwest parts.","ja":"大漢渓が市域を横切り、市を南東部と北西部に二分している"},{"k":"life","zh":"八德是馬祖人在臺灣本島聚居人數最多的地方","en":"Bade is home to the largest Matsu islander community on Taiwan's main island.","ja":"八徳は、台湾本島で馬祖出身者が最も多く住む地域だ"},{"k":"life","zh":"龍岡因滇緬游擊部隊駐紮而有不少穆斯林，1967年建了清真寺","en":"Longgang has many Muslims from Yunnan-Burma guerrilla units; its mosque was built in 1967.","ja":"龍岡には滇緬ゲリラ部隊の駐屯で多くのムスリムが住み、1967年にモスクが建てられた"},{"k":"festival","zh":"2012年起舉辦國際動漫大展，還在國際機場設了機場展","en":"Since 2012 the city has held an international comics and animation fair, with a branch at the airport.","ja":"2012年から国際アニメ・漫画展を開き、国際空港内にも会場を設けた"}],
"TW-TNN":[{"k":"symbol","zh":"市鳥是水雉，市樹是鳳凰木","en":"Its city bird is the pheasant-tailed jacana; its tree is the royal poinciana.","ja":"市の鳥はレンカク（水雉）、市の木はホウオウボク"},{"k":"sport","zh":"職棒統一7-ELEVEn獅的主場所在地","en":"Home of the CPBL's Uni-President 7-Eleven Lions.","ja":"プロ野球・統一セブンイレブン・ライオンズの本拠地"},{"k":"people","zh":"前洋基投手王建民出生在關廟，2006年拿下大聯盟勝投王","en":"Ex-Yankees pitcher Chien-Ming Wang, born in Guanmiao, tied for the MLB wins lead in 2006.","ja":"元ヤンキースの王建民は関廟生まれ。2006年に大リーグ最多勝"},{"k":"record","zh":"農耕地面積全臺第一","en":"It has the most farmland of any county or city in Taiwan.","ja":"耕地面積は台湾一"},{"k":"life","zh":"2015年市府把英語列為第二官方語言","en":"In 2015 the city government made English its second official language.","ja":"2015年、市政府は英語を第二公用語にした"},{"k":"festival","zh":"七夕替滿16歲的孩子「做十六歲」，鑽過七娘媽亭象徵成年","en":"On Qixi, 16-year-olds \"do sixteen\", crawling under a paper shrine to mark adulthood.","ja":"七夕に16歳を迎えた子は「做十六歳」を行い、七娘媽亭をくぐって成人を祝う"},{"k":"origin","zh":"荷蘭人築城的沙洲古稱「大員」，後來演變成整座島的名字","en":"The sandbar where the Dutch built their fort was called Tayouan, which became the name of the whole island.","ja":"オランダ人が城を築いた砂州は「大員」と呼ばれ、のちに島全体の名になった"},{"k":"work","zh":"偶像劇《想見你》1998年的校園戲在這裡拍，主角們還在此同住兩個月","en":"The 1998 school scenes of the drama Someday or One Day were shot here; the leads lived here for two months.","ja":"ドラマ『時をかける愛』の1998年の学園シーンはここで撮影。主演陣は2か月同居した"},{"k":"people","zh":"鄭成功1662年趕走荷蘭人後不久，就在這裡病逝","en":"Koxinga died here in 1662, only months after driving out the Dutch.","ja":"鄭成功は1662年、オランダ人を追い出して間もなくこの地で病死した"},{"k":"history","zh":"鄭成功圍攻熱蘭遮城約九個月，1662年荷蘭長官揆一投降","en":"Koxinga besieged Fort Zeelandia for about nine months until Dutch governor Coyett surrendered in 1662.","ja":"鄭成功はゼーランディア城を約9か月包囲し、1662年にオランダ長官コイエットが降伏した"},{"k":"people","zh":"寫出《台灣文學史綱》的作家葉石濤，就出生在這裡","en":"Yeh Shih-tao, author of the first Taiwanese-written history of Taiwanese literature, was born here.","ja":"『台湾文学史綱』を著した作家・葉石濤は、この地の生まれ"},{"k":"people","zh":"新化出身的作家楊逵寫了〈送報伕〉，戰後被判刑12年、關在綠島","en":"Xinhua-born writer Yang Kui wrote 'The Newspaper Boy' and was later sentenced to 12 years on Green Island.","ja":"新化出身の作家・楊逵は『新聞配達夫』を書き、戦後は懲役12年で緑島に送られた"},{"k":"sport","zh":"1990年中華職棒史上第一場比賽，在這裡的市立棒球場開打","en":"The first-ever CPBL game was played at this city's municipal baseball stadium in 1990.","ja":"1990年、台湾プロ野球（CPBL）史上初の試合がこの市の市立野球場で行われた"},{"k":"sport","zh":"中職最長比賽：2009年總冠軍賽在這裡打了17局、6小時14分","en":"The CPBL's longest game, 17 innings and 6 h 14 min, was a 2009 Taiwan Series game played here.","ja":"2009年の台湾シリーズで、CPBL最長となる17回・6時間14分の試合がここで行われた"},{"k":"work","zh":"電影《孤味》以這裡為舞台，陳淑芳飾演餐廳老闆奪下金馬影后","en":"In 'Little Big Women', set here, Chen Shu-fang plays a restaurant owner and won the Golden Horse for Best Actress.","ja":"映画『孤味』はこの地が舞台で、料理店の女主人を演じた陳淑芳は金馬奨主演女優賞を受賞"},{"k":"festival","zh":"西港刈香逢丑、辰、未、戌年舉行，三年一科，最後焚燒王船","en":"The Xigang incense procession is held every three years and ends with the burning of a royal boat.","ja":"西港刈香は丑・辰・未・戌年の3年に一度行われ、最後に王船を燃やす"},{"k":"origin","zh":"安平之名，來自鄭成功的故鄉福建南安安平","en":"Anping was named by Koxinga's regime after Anping in Nan'an, Fujian, his ancestral home.","ja":"安平の名は、鄭成功の故郷である福建省南安の安平にちなむ"},{"k":"record","zh":"巴克禮1885年在這裡創辦的白話字教會報，是臺灣發行最久的報紙","en":"The romanized-Taiwanese church paper Thomas Barclay founded here in 1885 is Taiwan's longest-running newspaper.","ja":"バークレーが1885年にここで創刊したローマ字の教会報は、台湾で最も長く続く新聞"},{"k":"record","zh":"馬雅各1865年開設的看西街醫館，是臺灣最早的西式醫院","en":"James Maxwell's clinic, opened here in 1865, was Taiwan's earliest Western-style hospital.","ja":"1865年にマクスウェルが開いた看西街医館は、台湾最初の西洋式病院"},{"k":"record","zh":"1932年開幕的林百貨，是臺灣唯一頂樓設有神社的百貨公司","en":"Hayashi Department Store, opened in 1932, is Taiwan's only department store with a Shinto shrine on its roof.","ja":"1932年開業のハヤシ百貨店は、屋上に神社がある台湾唯一の百貨店"},{"k":"history","zh":"1915年的噍吧哖事件，是日治時期規模最大的武裝抗日事件","en":"The 1915 Tapani Incident was the largest armed uprising against Japanese rule in Taiwan.","ja":"1915年のタパニー事件は、日本統治時代で最大規模の武装抗日事件"},{"k":"history","zh":"1876年完工的億載金城由法國工程師設計，配有英國阿姆斯壯大砲","en":"Eternal Golden Castle, finished in 1876, was designed by French engineers and armed with British Armstrong guns.","ja":"1876年完成の億載金城はフランス人技師の設計で、イギリスのアームストロング砲を備えた"},{"k":"nature","zh":"這裡曾有大潟湖「台江內海」，1823年大雨後迅速淤積成陸地","en":"A great lagoon, the Taijiang Inner Sea, lay here until silt from an 1823 storm turned it into land.","ja":"かつてここにあった潟湖「台江内海」は、1823年の大雨で急速に陸地に変わった"},{"k":"history","zh":"左鎮人化石曾被視為臺灣最古老的人類，2015年重測只有約三千年","en":"Zuozhen Man fossils, once thought to be Taiwan's oldest humans, were re-dated in 2015 to only about 3,000 years.","ja":"左鎮人の化石は台湾最古の人類とされたが、2015年の再測定で約3000年前のものと判明した"},{"k":"nature","zh":"關子嶺溫泉的泉水灰黑混濁，是臺灣唯一的泥漿溫泉","en":"Guanziling's grey, muddy water makes it Taiwan's only mud hot spring.","ja":"関子嶺温泉は灰黒色に濁った湯で、台湾唯一の泥湯温泉"},{"k":"brand","zh":"統一企業1967年在永康創立，從麵粉與飼料起家","en":"Uni-President Enterprises was founded in Yongkang here in 1967, starting with flour and animal feed.","ja":"統一企業は1967年に永康で創業し、小麦粉と飼料から始まった"},{"k":"brand","zh":"香腸品牌黑橋牌，1957年從運河旁的家庭肉品工廠起家","en":"Sausage brand Black Bridge began in 1957 as a family meat workshop beside the city's canal.","ja":"ソーセージの「黒橋牌」は1957年、運河沿いの家族経営の食肉工場から始まった"},{"k":"legend","zh":"清代節婦陳守娘不肯改嫁被害死，成為這裡最有名的厲鬼傳說","en":"Qing-era widow Chen Shou-niang, killed for refusing to remarry, became the city's most famous vengeful ghost.","ja":"再婚を拒んで殺された清代の寡婦・陳守娘は、この地で最も有名な怨霊伝説となった"},{"k":"food","zh":"番茄沾醬油膏、薑末和糖吃，被稱為這裡最古老的小吃","en":"Tomatoes dipped in soy paste, ginger and sugar are called the city's oldest snack.","ja":"トマトに醤油膏・生姜・砂糖をつけて食べるのが、この地最古の小吃とされる"},{"k":"food","zh":"據說荷蘭人從印尼引進虱目魚，在這裡開始養殖","en":"The Dutch are said to have brought milkfish from Indonesia and begun farming it here.","ja":"オランダ人がインドネシアからサバヒーを持ち込み、ここで養殖を始めたとされる"},{"k":"food","zh":"傳統早餐是用月桃葉包花生的菜粽，再配一碗味噌湯","en":"A classic local breakfast: peanut rice dumplings wrapped in shell-ginger leaves, with a bowl of miso soup.","ja":"月桃の葉で包んだ落花生入りの菜粽に味噌汁を添えるのが、この地の伝統的な朝食"},{"k":"food","zh":"口味偏甜，與日治時期糖業興盛、糖被大量用來調味有關","en":"Local food tastes sweet partly because sugar was a major product here under Japanese rule.","ja":"料理が甘めなのは、日本統治時代に製糖業が栄え砂糖を多用したためとされる"},{"k":"symbol","zh":"麻豆的文旦柔軟多汁，連品種名都冠上當地地名","en":"Madou's juicy pomelo is so prized that the cultivar itself bears the town's name: Madou wentan.","ja":"麻豆の文旦は果肉が柔らかく、品種名にも「麻豆」の地名が付く"}],
"TW-TPE":[{"k":"symbol","zh":"代表吉祥物是臺灣黑熊「熊讚」，原本是2017年世大運的吉祥物，後來轉正為市府吉祥物","en":"Its official mascot is Bravo, a Formosan black bear first created for the 2017 Summer Universiade.","ja":"公式マスコットはタイワンツキノワグマの「熊讚」。もとは2017年ユニバーシアードのマスコットだった"},{"k":"record","zh":"1932年開幕的菊元百貨店是臺灣第一家百貨公司，1935年臺灣第一座紅綠燈也設在附近","en":"Kikumoto, Taiwan's first department store, opened here in 1932; Taiwan's first traffic light followed nearby in 1935.","ja":"1932年開業の菊元百貨店は台湾初の百貨店。1935年には台湾初の信号機も近くに設置された"},{"k":"record","zh":"2017年11月30日，山區的彩虹連續高掛9小時，獲金氏世界紀錄認證","en":"On 30 Nov 2017 a rainbow over its mountains lasted 9 hours, certified by Guinness World Records.","ja":"2017年11月30日、山あいに虹が9時間出続け、ギネス世界記録に認定された"},{"k":"life","zh":"2000年7月全臺最早實施垃圾費隨袋徵收，丟垃圾得用專用垃圾袋","en":"In July 2000 it became the first in Taiwan to charge for trash by the bag: garbage must go in official paid bags.","ja":"2000年7月、台湾で最初にごみ袋有料化を実施。ごみは指定の有料袋で出さなければならない"},{"k":"origin","zh":"舊市街「艋舺」的名字，來自凱達格蘭語的「獨木舟」","en":"The old district name Monga (Bangka) comes from the Ketagalan word for \"canoe\".","ja":"旧市街「艋舺（モンガ）」の名は、ケタガラン族の言葉で「丸木舟」を意味する"},{"k":"sport","zh":"職棒味全龍的主場所在地","en":"Home of the CPBL's Wei Chuan Dragons.","ja":"プロ野球・味全ドラゴンズの本拠地がある"},{"k":"work","zh":"白先勇小說《孽子》以這裡的新公園（今二二八和平紀念公園）為主要舞台","en":"Pai Hsien-yung's novel Crystal Boys is set mainly in the city's New Park (now 228 Peace Memorial Park).","ja":"白先勇の小説『孽子』の主な舞台は、市内の新公園（現・二二八和平紀念公園）"},{"k":"festival","zh":"1996年起每逢農曆春節前，迪化街會舉辦全臺首創的「年貨大街」","en":"Since 1996, Dihua Street has hosted Taiwan's first \"New Year Shopping Street\" before each Lunar New Year.","ja":"1996年から旧正月前に迪化街で台湾初の「年貨大街」（正月用品市）が開かれる"},{"k":"history","zh":"1945年臺灣地區的日軍受降典禮，在公會堂（今中山堂）舉行","en":"In 1945, the Japanese surrender ceremony for Taiwan was held at the Public Hall, now Zhongshan Hall.","ja":"1945年、台湾地区の日本軍の降伏式典が公会堂（現在の中山堂）で行われた"},{"k":"history","zh":"1947年2月27日太平町一帶的私菸查緝衝突，引爆了二二八事件","en":"A clash over contraband cigarettes here on 27 February 1947 triggered the February 28 Incident.","ja":"1947年2月27日、太平町付近での闇たばこ取り締まりの衝突が二・二八事件の発端となった"},{"k":"history","zh":"1990年的野百合學運在這裡發生，推動臺灣走向多黨民主","en":"The 1990 Wild Lily student movement here helped push Taiwan toward multi-party democracy.","ja":"1990年の野百合学生運動がここで起こり、台湾の複数政党制民主化を後押しした"},{"k":"history","zh":"1960年6月，美國總統艾森豪曾訪問這座城市","en":"U.S. President Dwight Eisenhower visited this city in June 1960.","ja":"1960年6月、アメリカのアイゼンハワー大統領がこの街を訪問した"},{"k":"origin","zh":"1709年泉州人以「陳賴章」墾號申請開墾的「大佳臘」，就是這一帶","en":"In 1709, Quanzhou settlers applied under the 'Chen Laizhang' charter to farm 'Dajiala', which is this area.","ja":"1709年に泉州人が「陳頼章」墾号で開墾を申請した「大佳臘」とは、この一帯のことだ"},{"k":"origin","zh":"大稻埕的名字，來自當地居民共用的大片曬穀廣場","en":"The Dadaocheng district is named for a large public rice-drying yard shared by residents.","ja":"大稲埕という地名は、住民が共同で使った大きな稲干し場に由来する"},{"k":"legend","zh":"傳說鄭成功投出寶劍降服興風作浪的水怪，劍潭因此得名","en":"Legend says Koxinga threw his sword into a river pool to subdue a monster, giving Jiantan ('Sword Pool') its name.","ja":"鄭成功が宝剣を投げ入れて水怪を鎮めたという伝説が、剣潭の名の由来とされる"},{"k":"legend","zh":"劍潭另一傳說是荷蘭人把劍插進潭邊的茄苳樹，樹皮長合將劍包在裡面","en":"Another Jiantan legend says a Dutchman thrust a sword into a tree by the pool, and the bark grew over it.","ja":"剣潭の別の伝説では、オランダ人が潭のほとりのアカギに剣を刺し、樹皮が剣を包み込んだという"},{"k":"record","zh":"1913年落成的北投溫泉公共浴場，當時是東亞最大的溫泉公共浴場","en":"Beitou's public hot spring bathhouse, opened in 1913, was the largest in East Asia at the time.","ja":"1913年完成の北投温泉公共浴場は、当時東アジア最大の温泉公衆浴場だった"},{"k":"record","zh":"1895年設立的芝山巖學堂是臺灣第一所西式小學，即今士林國小","en":"Zhishanyan School, founded in 1895, was Taiwan's first Western-style elementary school.","ja":"1895年創立の芝山巌学堂は台湾初の西洋式小学校で、現在の士林国小にあたる"},{"k":"record","zh":"1895年創建的臺大醫院，是臺灣歷史最悠久的西式醫院","en":"National Taiwan University Hospital, founded in 1895, is Taiwan's oldest Western-style hospital.","ja":"1895年創設の台湾大学医学部附属病院は、台湾で最も歴史ある西洋式病院だ"},{"k":"record","zh":"1908年成立的國立臺灣博物館，是臺灣歷史最悠久的博物館","en":"The National Taiwan Museum, founded in 1908, is Taiwan's oldest museum.","ja":"1908年創立の国立台湾博物館は、台湾で最も古い博物館である"},{"k":"record","zh":"日治時期的放送局（今二二八紀念館）是臺灣第一個廣播電臺","en":"A Japanese-era broadcasting station, now the 228 Memorial Museum, was Taiwan's first radio station.","ja":"日本統治時代の放送局（現在の二二八記念館）は、台湾初のラジオ局だった"},{"k":"record","zh":"1983年開館的市立美術館，是臺灣第一座專門的現代美術館","en":"The city's Fine Arts Museum, founded in 1983, was Taiwan's first museum devoted to modern art.","ja":"1983年開館の市立美術館は、台湾初の現代美術専門の美術館だ"},{"k":"nature","zh":"新店溪與大漢溪在萬華附近匯成淡水河，基隆河再於關渡匯入","en":"The Xindian and Dahan rivers merge near Wanhua to form the Tamsui, which the Keelung River joins at Guandu.","ja":"新店渓と大漢渓が萬華付近で合流して淡水河となり、基隆河が関渡で合流する"},{"k":"nature","zh":"2016年1月24日寒流來襲，市區測站首次觀測到雨夾雪","en":"On 24 January 2016, the city's weather station recorded sleet, its first ever solid precipitation.","ja":"2016年1月24日の寒波で、市内の観測所が初めてみぞれ（固体降水）を観測した"},{"k":"brand","zh":"日治時期1923年，陽明山竹子湖設立了蓬萊米的原種田","en":"In 1923, a seed-rice field for Horai (Ponlai) rice was set up at Zhuzihu on Yangmingshan.","ja":"1923年、陽明山の竹子湖に蓬莱米の原種田が設けられた"},{"k":"festival","zh":"每年約2月至5月，陽明山竹子湖會舉辦海芋季","en":"Every year from about February to May, Zhuzihu on Yangmingshan holds a calla lily festival.","ja":"毎年2月から5月ごろ、陽明山の竹子湖でカラー（海芋）の花祭りが開かれる"},{"k":"brand","zh":"1869年英商陶德從大稻埕運出烏龍茶，以「Formosa Tea」之名銷往紐約","en":"In 1869, British merchant John Dodd shipped oolong from Dadaocheng to New York as 'Formosa Tea'.","ja":"1869年、英国商人ジョン・ドッドが大稲埕から烏龍茶を「Formosa Tea」としてニューヨークへ輸出した"},{"k":"brand","zh":"總部設在中山北路的大同公司，1960年推出了家喻戶曉的大同電鍋","en":"Tatung, headquartered on Zhongshan North Road, launched its iconic electric rice cooker in 1960.","ja":"中山北路に本社を置く大同公司は、1960年におなじみの大同電鍋を発売した"},{"k":"food","zh":"裕仁皇太子來訪時，總督官邸曾為他設「臺灣料理」御宴","en":"When Crown Prince Hirohito visited, a Taiwanese-cuisine banquet was held for him at the Governor-General's residence.","ja":"裕仁皇太子が訪れた際、総督官邸で「台湾料理」の御宴が催された"},{"k":"food","zh":"2018年米其林指南推出這座城市的版本，是第八本以亞洲城市為對象的米其林","en":"In 2018 the Michelin Guide launched an edition for this city, its eighth for an Asian city.","ja":"2018年にミシュランガイドのこの街の版が刊行され、アジアの都市では8番目だった"},{"k":"food","zh":"2005年起，這座城市開始舉辦國際牛肉麵節","en":"Since 2005, the city has hosted an international beef noodle festival.","ja":"2005年から、この街で国際牛肉麺フェスティバルが開かれるようになった"},{"k":"festival","zh":"大稻埕霞海城隍廟每年農曆五月十三舉行迎城隍，香火鼎盛","en":"Dadaocheng's Xiahai City God Temple holds a grand procession every 13th day of the 5th lunar month.","ja":"大稲埕の霞海城隍廟では、毎年旧暦5月13日に城隍神の祭り「迎城隍」が盛大に行われる"},{"k":"symbol","zh":"二戰時在緬甸運補的大象林旺，1954年來到這裡的動物園，成為明星動物","en":"Lin Wang, an elephant that hauled supplies in WWII Burma, joined the city zoo in 1954 and became its star.","ja":"第二次大戦中ビルマで物資を運んだゾウの林旺は、1954年にこの街の動物園に来て人気者になった"},{"k":"work","zh":"楊德昌電影《牯嶺街少年殺人事件》以1960年前後的這座城市為舞台","en":"Edward Yang's film A Brighter Summer Day (1991) is set here around 1960.","ja":"エドワード・ヤン監督の映画『牯嶺街少年殺人事件』は、1960年前後のこの街が舞台"},{"k":"sport","zh":"2009年夏季聽障奧運在這座城市舉行","en":"The 2009 Summer Deaflympics were held in this city.","ja":"2009年の夏季デフリンピックがこの街で開催された"},{"k":"people","zh":"畫家張大千晚年住在外雙溪的摩耶精舍，骨灰就葬在園內梅丘","en":"Painter Zhang Daqian spent his last years at Moye Residence in Waishuangxi; his ashes lie in its garden.","ja":"画家の張大千は晩年を外双渓の摩耶精舎で過ごし、遺骨は庭の梅丘に葬られた"},{"k":"people","zh":"1921年蔣渭水在大稻埕開設大安醫院，同年參與創立臺灣文化協會","en":"In 1921 Chiang Wei-shui opened Da'an Hospital in Dadaocheng and co-founded the Taiwanese Cultural Association.","ja":"1921年、蒋渭水は大稲埕に大安医院を開き、同年に台湾文化協会の創立に加わった"}],
"TW-TTT":[{"k":"symbol","zh":"縣鳥是臺灣特有種烏頭翁","en":"Its county bird is Styan's bulbul, a species found only in Taiwan.","ja":"県の鳥は台湾固有のヒヨドリの仲間、烏頭翁"},{"k":"record","zh":"海岸線長達176公里，是全臺最長的縣市","en":"Its 176 km coastline is the longest of any Taiwanese county or city.","ja":"海岸線は176kmで、台湾の県市で最長"},{"k":"record","zh":"原住民人口比例是全國最高的縣市","en":"It has the highest share of Indigenous residents of any county or city in Taiwan.","ja":"先住民の人口比率が全国で最も高い県市"},{"k":"record","zh":"縣內史前遺址的數量是全臺最多","en":"It has more prehistoric sites than any other county or city in Taiwan.","ja":"先史遺跡の数は台湾最多"},{"k":"life","zh":"算上空軍志航基地，縣內共有四座機場，數量全臺最多","en":"Counting Chihhang Air Base, it has four airports, more than any other county.","ja":"空軍志航基地を含め空港が4つあり、数は台湾最多"},{"k":"people","zh":"效力過日本火腿、讀賣巨人的旅日球星陽岱鋼在這裡出生","en":"Yoh Daikan (Yang Dai-kang), who starred for Japan's Nippon-Ham Fighters and Yomiuri Giants, was born here.","ja":"日本ハム・巨人で活躍した陽岱鋼はここの生まれ"},{"k":"work","zh":"金城武在2013年長榮航空廣告裡坐在樹下喝茶，那棵樹從此被叫做「金城武樹」","en":"After Takeshi Kaneshiro sipped tea under a tree in a 2013 EVA Air ad, it became the \"Kaneshiro Tree\".","ja":"2013年の長栄航空CMで金城武が木の下でお茶を飲み、その木は「金城武の木」に"},{"k":"origin","zh":"太麻里源自排灣語「太陽照耀的肥沃土地」，2000年在此舉辦迎千禧曙光","en":"Taimali comes from Paiwan for \"fertile land where the sun shines\"; it hosted the 2000 millennium sunrise event.","ja":"太麻里はパイワン語で「太陽が照らす肥沃な土地」。2000年に千年紀の初日の出イベント"},{"k":"history","zh":"荷蘭人聽說這一帶盛產黃金，1642年派兵征討，並在卑南覓駐軍","en":"Lured by rumors of gold, the Dutch sent troops here in 1642 and garrisoned Pimaba.","ja":"金の噂を聞いたオランダ人は1642年に兵を送り、卑南覓に駐屯した"},{"k":"history","zh":"牡丹社事件後沈葆楨設立卑南廳，是清廷在這裡設官治理的開始","en":"After the Mudan Incident, Shen Baozhen set up Beinan Subprefecture, starting formal Qing rule here.","ja":"牡丹社事件の後、沈葆楨が卑南庁を設け、ここで清朝の統治が始まった"},{"k":"record","zh":"是臺灣最晚有漢人移民開墾的地區，直到19世紀末才開發","en":"It was the last part of Taiwan settled by Han Chinese immigrants, in the late 19th century.","ja":"台湾で最も遅く漢人が入植した地域で、開拓は19世紀末だった"},{"k":"history","zh":"日本人1898年開建的卑南大圳，1941年完工後灌溉面積增為約四倍","en":"The Beinan Canal, begun by the Japanese in 1898 and finished in 1941, roughly quadrupled irrigated land.","ja":"日本人が1898年に着工した卑南大圳は1941年に完成し、灌漑面積を約4倍にした"},{"k":"history","zh":"1970年泰源監獄的政治犯奪槍起事，史稱「泰源事件」","en":"In 1970 political prisoners at Taiyuan Prison seized guns in a failed uprising, the Taiyuan Incident.","ja":"1970年、泰源監獄の政治犯が銃を奪って蜂起した「泰源事件」が起きた"},{"k":"history","zh":"1981年起蘭嶼設置核廢料貯存場，引發當地居民長年抗爭","en":"Since 1981 Orchid Island has hosted a nuclear waste storage site, long opposed by locals.","ja":"1981年から蘭嶼に核廃棄物の貯蔵場が置かれ、住民の長い反対運動が続いている"},{"k":"origin","zh":"蘭嶼舊名「紅頭嶼」，1940年代末以島上的蘭花改成今名","en":"Orchid Island was once called Hongtou Islet and was renamed after its orchids in the late 1940s.","ja":"蘭嶼の旧名は「紅頭嶼」で、1940年代末に島の蘭にちなんで改名された"},{"k":"origin","zh":"綠島舊名「火燒島」，1948年才改成今名","en":"Green Island was formerly called Huoshao (\"burning\") Island and was renamed in 1948.","ja":"緑島の旧名は「火焼島」で、1948年に現在の名に改められた"},{"k":"record","zh":"綠島的「大香菇」是已知最大最古老的活珊瑚群之一，2016年颱風後斷裂","en":"Green Island's \"Big Mushroom\" is one of the largest, oldest known living corals; a 2016 typhoon broke it.","ja":"緑島の「大香菇」は最大・最古級の生きたサンゴ群体の一つだが、2016年の台風で折れた"},{"k":"people","zh":"「亞洲鐵人」楊傳廣在1960年羅馬奧運奪得十項全能銀牌，是我國首面奧運獎牌","en":"\"Asian Iron Man\" Yang Chuan-kwang, born here, won decathlon silver at Rome 1960, the ROC's first Olympic medal.","ja":"ここ出身の「アジアの鉄人」楊伝広は1960年ローマ五輪の十種競技で銀を取り、中華民国初の五輪メダルとなった"},{"k":"sport","zh":"出身這裡的楊傳廣1963年以9,121分創十項全能世界紀錄，史上首位破9,000分","en":"Local hero Yang Chuan-kwang set a decathlon world record of 9,121 points in 1963, the first ever over 9,000.","ja":"ここ出身の楊伝広は1963年に十種競技で9121点の世界記録を出し、初めて9000点を超えた"},{"k":"people","zh":"歌手胡德夫生於這裡，是第一位公開演唱禁歌〈美麗島〉的人","en":"Singer Hu Te-fu, born here, gave the first public performance of the once-banned song \"Formosa.\"","ja":"歌手の胡徳夫はここの生まれで、禁じられた歌「美麗島」を初めて公の場で歌った"},{"k":"festival","zh":"元宵節「炸寒單」，赤膊男子扮寒單爺讓人丟鞭炮炸，說是替怕冷的神明取暖","en":"At the Lantern Festival, bare-chested men playing Lord Handan are pelted with firecrackers to \"warm\" the god.","ja":"元宵節の「炸寒単」では、上半身裸の男が寒単爺に扮し、寒がりの神を温めるため爆竹を浴びる"},{"k":"record","zh":"長濱鄉八仙洞出土的長濱文化，是臺灣已知最古老的史前文化","en":"The Changbin Culture found at the Baxian Caves here is the oldest known prehistoric culture in Taiwan.","ja":"長浜郷の八仙洞で見つかった長浜文化は、台湾で知られる最古の先史文化だ"},{"k":"record","zh":"蘭嶼的達悟族是臺灣唯一擁有金屬工藝傳統的原住民族","en":"The Tao of Orchid Island are the only Taiwanese Indigenous people with a metalworking tradition.","ja":"蘭嶼のタオ族は、台湾で唯一金属加工の伝統を持つ原住民族だ"},{"k":"life","zh":"蘭嶼達悟族的語言，與菲律賓巴丹群島的伊巴丹人相近","en":"The Tao language of Orchid Island is closely related to that of the Ivatan in the Philippines' Batanes.","ja":"蘭嶼のタオ族の言葉は、フィリピン・バタン諸島のイバタン人の言葉と近い"},{"k":"life","zh":"達悟族長年被稱為「雅美族」，這個名字其實源於日本學者的誤解","en":"The Tao were long called \"Yami,\" a name that came from a Japanese anthropologist's misunderstanding.","ja":"タオ族が長く「ヤミ族」と呼ばれたのは、日本の人類学者の聞き違いが元だ"},{"k":"legend","zh":"達悟族神話說，人類的祖先一個從石頭、一個從竹林裡誕生","en":"A Tao myth says the first humans were born, one from a stone and one from a bamboo grove.","ja":"タオ族の神話では、人類の祖先は石と竹林からそれぞれ生まれたとされる"},{"k":"life","zh":"2018年蘭嶼達悟族與復活節島的拉帕努伊人締結「姊妹部落」","en":"In 2018 the Tao of Orchid Island became \"sister tribes\" with the Rapa Nui of Easter Island.","ja":"2018年、蘭嶼のタオ族はイースター島のラパ・ヌイの人々と「姉妹部族」を結んだ"},{"k":"work","zh":"電影《只有大海知道》以蘭嶼小學師生組表演隊的真實故事為藍本","en":"The 2018 film Long Time No Sea is based on a true story of a school performance troupe on Orchid Island.","ja":"2018年の映画『只有大海知道』は、蘭嶼の小学校で生まれた芸能チームの実話がもとだ"},{"k":"symbol","zh":"蘭嶼角鴞是分布在蘭嶼的特有亞種，達悟語稱牠「都都霧」","en":"The Lanyu scops owl is an endemic subspecies found on Orchid Island.","ja":"ランユウコノハズクは蘭嶼にすむ固有亜種で、タオ語で「都都霧」と呼ばれる"},{"k":"life","zh":"人口密度是全國各縣市中最低的","en":"It has the lowest population density of any county or city in Taiwan.","ja":"人口密度は台湾の県市の中で最も低い"}],
"TW-TXG":[{"k":"origin","zh":"清代舊稱「大墩」","en":"In the Qing era it was called Toā-tun (Big Mound).","ja":"清代の旧名は「大墩」"},{"k":"symbol","zh":"市鳥是白耳畫眉，市樹是臺灣五葉松","en":"Its city bird is the white-eared sibia; its city tree is the Taiwan white pine.","ja":"市の鳥はミミジロチメドリ（白耳画眉）、市の木はタイワンゴヨウマツ"},{"k":"sport","zh":"職棒中信兄弟以這裡的洲際棒球場為主場","en":"The CPBL's CTBC Brothers use the Intercontinental Baseball Stadium here as their home.","ja":"プロ野球・中信兄弟の本拠地は、ここの洲際野球場"},{"k":"record","zh":"2013年獲國際棒球總會頒發世界第一座「世界棒球之都」榮譽","en":"In 2013 the IBAF named it the world's first \"World Baseball City\".","ja":"2013年、国際野球連盟から世界初の「世界野球の都」の称号を受けた"},{"k":"record","zh":"市內的中區是全國面積最小的市轄區","en":"Its Central District is the smallest city district in the country.","ja":"市内の中区は全国で面積が最も小さい区"},{"k":"record","zh":"清泉崗基地是全臺最大的空軍基地","en":"Ching Chuan Kang Air Base is Taiwan's largest air force base.","ja":"清泉崗基地は台湾最大の空軍基地"},{"k":"festival","zh":"清代稻田鬧蟲害時請媽祖遶境驅蟲，演變成每年的「旱溪媽祖遶境十八庄」","en":"Born from a Qing-era plea to drive pests from the rice fields, the Hanxi Mazu procession tours 18 villages every year.","ja":"清代に稲の害虫を追い払う巡行を頼んだのが始まり。毎年「旱渓媽祖十八庄巡行」が行われる"},{"k":"people","zh":"有「臺灣第一才子」之稱的作家呂赫若出生在潭子","en":"Writer Lu Heruo, dubbed \"Taiwan's foremost talent\", was born in Tanzi.","ja":"「台湾第一の才子」と呼ばれた作家・呂赫若は潭子の生まれ"},{"k":"history","zh":"1887年劉銘傳曾選這裡作為臺灣省城，後任巡撫卻把省城移到臺北","en":"In 1887 Liu Ming-chuan chose this spot for Taiwan's provincial capital, but his successor moved it to Taipei.","ja":"1887年、劉銘伝はここを台湾省の省都に選んだが、後任の巡撫が台北へ移した"},{"k":"history","zh":"平埔族曾在此組成「大肚王國」，荷蘭人稱其君主為「中晝之王」","en":"Plains peoples here formed the Middag Kingdom, whose ruler the Dutch called the 'Keizer van Middag'.","ja":"平埔族が「大肚王国」を築き、オランダ人はその君主を「昼の王」と呼んだ"},{"k":"history","zh":"1958年起臺灣省議會設在霧峰，直到精省後才改制","en":"From 1958 the Taiwan Provincial Assembly sat in Wufeng here until the province was downsized.","ja":"1958年から台湾省議会が霧峰に置かれ、精省後まで続いた"},{"k":"history","zh":"1915年林獻堂等仕紳出資，創辦第一所專收臺灣子弟的中學校","en":"In 1915 local gentry funded the first middle school for Taiwanese youth, today's First Senior High here.","ja":"1915年、林献堂ら台湾人有力者の出資で、台湾人子弟のための初の中学校が開校した"},{"k":"history","zh":"1913年賴來響應羅福星起事，在東勢襲擊日警後遭擊斃","en":"In 1913 Lai Lai raided Japanese police in Dongshi in support of Luo Fu-hsing's plot and was killed.","ja":"1913年、頼来が羅福星の蜂起に呼応して東勢で日本警察を襲撃し、射殺された"},{"k":"history","zh":"后里馬場是1937年總督府設立的種馬牧場，戰後由軍方接手繁殖軍馬","en":"Houli Horse Ranch was set up as a stud farm in 1937 and bred horses for the military after the war.","ja":"后里馬場は1937年に総督府が設けた種馬牧場で、戦後は軍が軍馬を繁殖させた"},{"k":"people","zh":"霧峰林家的林獻堂，領導臺灣議會設置請願運動長達14年","en":"Lin Hsien-tang of the Wufeng Lin family led a 14-year campaign for a Taiwanese parliament.","ja":"霧峰林家の林献堂は、台湾議会設置請願運動を14年にわたって率いた"},{"k":"legend","zh":"被傳為劫富濟貧「義賊」的廖添丁，出生在清水","en":"Liao Tian-ding, the folk 'righteous bandit' said to rob the rich to help the poor, was born in Qingshui.","ja":"金持ちから奪い貧者に施した「義賊」と伝わる廖添丁は、清水の生まれ"},{"k":"origin","zh":"豐原舊名「葫蘆墩」，1920年因稻米優良，取日本神話「豐葦原瑞穗國」改名","en":"Fengyuan, once Huludun, was renamed in 1920 after a Japanese mythic name for a land of fine rice.","ja":"豊原の旧名は「葫蘆墩」。米の良さから1920年に「豊葦原瑞穂国」にちなみ改名した"},{"k":"origin","zh":"霧峰舊稱「阿罩霧」，源自平埔族社名，1920年改成現名","en":"Wufeng was formerly Atabu, from a plains tribe's village name, and took its present name in 1920.","ja":"霧峰の旧称「阿罩霧」は平埔族の社名に由来し、1920年に現名になった"},{"k":"origin","zh":"清水舊稱「牛罵頭」，1920年因山腳下泉水清澈而改名","en":"Qingshui, once called Gumach (Niumatou), was renamed 'Clear Water' in 1920 for its pure spring.","ja":"清水の旧称は「牛罵頭」。1920年、山麓の泉が清らかなことから改名した"},{"k":"origin","zh":"后里原叫「內埔」，1955年因屏東已有內埔鄉，改用最大聚落的名字","en":"Houli was called Neipu until 1955, renamed because Pingtung already had a Neipu Township.","ja":"后里は元は内埔と呼ばれたが、屏東に同名の郷があったため1955年に改名した"},{"k":"brand","zh":"捷安特的母公司巨大機械，1972年由劉金標等人在大甲創立","en":"Giant, the bicycle maker, was founded in Dajia here in 1972 by King Liu and partners.","ja":"自転車メーカーのジャイアントは、1972年に劉金標らが大甲で創業した"},{"k":"brand","zh":"后里有「薩克斯風的故鄉」之稱，設有張連昌薩克斯風博物館","en":"Houli is known as the hometown of Taiwan's saxophone industry and has a saxophone museum.","ja":"后里は「サクソフォンの故郷」と呼ばれ、張連昌サクソフォン博物館がある"},{"k":"brand","zh":"1970至80年代臺灣外銷漆器約九成產自豐原","en":"In the 1970s–80s about 90% of Taiwan's exported lacquerware came from Fengyuan.","ja":"1970〜80年代、台湾の輸出漆器の約9割が豊原で作られていた"},{"k":"food","zh":"春水堂1983年在四維街開業，1987年正式推出珍珠奶茶","en":"Chun Shui Tang opened here in 1983 and officially put pearl milk tea on its menu in 1987.","ja":"春水堂は1983年にここで創業し、1987年にタピオカミルクティーを正式に売り出した"},{"k":"food","zh":"豐原的葫蘆墩米在日治時期曾作為御用米供應日本","en":"Huludun rice from Fengyuan was supplied to Japan as imperial-grade rice during Japanese rule.","ja":"豊原の葫蘆墩米は、日本統治時代に御用米として日本へ供給された"},{"k":"symbol","zh":"冰河時期孑遺的櫻花鉤吻鮭，只生活在大甲溪上游的七家灣溪一帶","en":"The Formosan landlocked salmon, an Ice Age relic, survives only in upper Dajia River streams here.","ja":"氷河期の遺存種タイワンマスは、大甲渓上流の七家湾渓一帯にだけ生息する"},{"k":"sport","zh":"1969年替臺灣拿下第一座少棒世界冠軍的金龍少棒隊，在這裡的忠孝國小集訓","en":"The Golden Dragons, Taiwan's first Little League world champions in 1969, trained at a school here.","ja":"1969年に台湾初のリトルリーグ世界一となった金龍少棒隊は、ここの忠孝国小で合宿した"},{"k":"sport","zh":"原本取得2019年東亞青年運動會主辦權，2018年卻被東亞奧協取消","en":"It won the right to host the 2019 East Asian Youth Games, but the hosting was revoked in 2018.","ja":"2019年の東アジアユース競技大会の開催権を得たが、2018年に取り消された"},{"k":"sport","zh":"2024年舉辦臺灣首次F1賽車道路展演，F1賽車首度在臺灣街頭奔馳","en":"In 2024 it hosted Taiwan's first F1 street demo, the first time an F1 car ran on Taiwanese roads.","ja":"2024年、台湾初のF1公道デモ走行が行われ、F1マシンが初めて台湾の街を走った"},{"k":"sport","zh":"1970年代國際知名的中華木蘭女子足球隊，主力來自宜寧中學","en":"The 1970s Mulan women's football team, famous abroad, drew most players from Yi-Ning High School here.","ja":"1970年代に国際的に知られた中華木蘭女子サッカーチームは、主力が宜寧中学の出身"},{"k":"record","zh":"1955年創立的東海大學，是臺灣第一所私立大學","en":"Tunghai University, founded here in 1955, was Taiwan's first private university.","ja":"1955年創立の東海大学は、台湾初の私立大学"},{"k":"record","zh":"龍井的火力發電廠是臺灣發電量最大的發電廠","en":"The coal-fired power plant in Longjing is Taiwan's largest power station by output.","ja":"龍井の火力発電所は、台湾で発電量が最大の発電所"},{"k":"record","zh":"1900年起以中區為核心的市區改正，是本島第一個完全人工重劃的城區","en":"From 1900 its downtown was replanned from scratch, the first fully planned city grid on Taiwan's main island.","ja":"1900年からの市区改正で、中区は本島初の完全に人工的に区画された市街となった"},{"k":"life","zh":"日治時期因綠川、柳川兩岸種柳，被宣傳為「臺灣的京都」","en":"With willows lining its Green and Willow rivers, Japanese-era promotions dubbed it the 'Kyoto of Taiwan'.","ja":"緑川・柳川の両岸に柳が植えられ、日本統治時代に「台湾の京都」と宣伝された"},{"k":"festival","zh":"東勢元宵有流傳百年的「新丁粄」比賽，是當地客家特有的元宵風俗","en":"Dongshi's Hakka hold a century-old 'new son' rice-cake contest every Lantern Festival.","ja":"東勢では元宵節に百年以上続く客家の「新丁粄」コンテストが開かれる"},{"k":"nature","zh":"大甲是全市唯一位在大安溪以北的行政區","en":"Dajia is the only district of this city lying north of the Da'an River.","ja":"大甲は市内で唯一、大安渓の北側にある区"}],
"TW-YUN":[{"k":"origin","zh":"縣名來自清代縣城所在的「○○坪」，那裡如今卻屬於南投縣竹山鎮","en":"Its name comes from its Qing-era seat, \"○○ Flat\", a spot that now belongs to Zhushan in Nantou.","ja":"県名は清代の県城があった「○○坪」に由来。そこは今、南投県竹山鎮にある"},{"k":"people","zh":"歌后鄧麗君出生在這裡的褒忠鄉","en":"Pop legend Teresa Teng was born in Baozhong Township here.","ja":"歌姫テレサ・テン（鄧麗君）はここの褒忠郷で生まれた"},{"k":"record","zh":"本島唯一不與任何直轄市接壤的縣","en":"The only county on the main island that borders no special municipality.","ja":"本島で唯一、どの直轄市とも接していない県"},{"k":"record","zh":"本島唯一縣內沒有與縣同名之「市」的縣","en":"The only county on the main island without a city sharing its name.","ja":"本島で唯一、県と同じ名の「市」がない県"},{"k":"festival","zh":"西螺福興宮的媽祖遶境是全臺時間最長、也是唯一在秋天舉行的媽祖遶境","en":"Xiluo's Fuxing Temple Mazu procession is Taiwan's longest, and the only one held in autumn.","ja":"西螺・福興宮の媽祖巡行は台湾で最も長く、唯一秋に行われる"},{"k":"life","zh":"土庫的蒜頭占全國貨源約七到八成","en":"Tuku supplies about 70 to 80 percent of Taiwan's garlic.","ja":"土庫のニンニクは全国の出荷量の7～8割を占める"},{"k":"record","zh":"三條崙海清宮被視為臺灣供奉包公的祖廟","en":"Santiaolun's Haiqing Temple is regarded as Taiwan's mother temple of Judge Bao.","ja":"三条崙の海清宮は、台湾の包公（包青天）信仰の祖廟とされる"},{"k":"festival","zh":"褒忠的大廍被稱為臺灣花鼓陣的發源地","en":"Dabu in Baozhong is called the birthplace of Taiwan's flower-drum troupes.","ja":"褒忠の大廍は台湾の花鼓陣の発祥地とされる"},{"k":"work","zh":"虎尾出身的黃俊雄，1970年推出的電視布袋戲創下97%收視率","en":"Huwei-born puppeteer Huang Chun-hsiung's 1970 TV glove-puppet drama hit a record 97% rating.","ja":"虎尾出身の黄俊雄が1970年に放送したテレビ布袋劇は、視聴率97%を記録した"},{"k":"work","zh":"總部在虎尾的霹靂，2000年布袋戲電影《聖石傳說》在臺灣票房勝過《玩具總動員2》","en":"Legend of the Sacred Stone (2000), by the Huwei-based Pili studio, beat Toy Story 2 at Taiwan's box office.","ja":"虎尾に本社を置く霹靂の映画『聖石伝説』は2000年、台湾で『トイ・ストーリー2』を上回る興行収入"},{"k":"life","zh":"虎尾人黃俊雄的電視布袋戲，1974年以「妨礙農工作息」為由遭停播","en":"In 1974 Huwei native Huang Chun-hsiung's hit puppet show was banned for 'disrupting farm and factory work'.","ja":"虎尾出身の黄俊雄のテレビ布袋劇は、1974年に「農工の仕事を妨げる」として放送停止に"},{"k":"brand","zh":"霹靂布袋戲的製作公司在虎尾擁有上萬坪的攝影棚","en":"Pili International Multimedia, maker of the Pili puppet dramas, runs a huge studio lot in Huwei.","ja":"霹靂布袋劇の制作会社は、虎尾に1万坪を超える撮影所を持つ"},{"k":"brand","zh":"麥寮工業專用港是臺灣第一座以BOT方式興建的民營工業港","en":"Mailiao Industrial Port was Taiwan's first privately run industrial harbor built under a BOT scheme.","ja":"麦寮工業専用港は、台湾初のBOT方式による民営の工業港"},{"k":"nature","zh":"古坑草嶺多次因山崩堵住溪流形成堰塞湖「草嶺潭」，又一再潰決消失","en":"Landslides at Caoling have repeatedly dammed a river into a lake that later burst and vanished.","ja":"古坑の草嶺では地すべりで何度もせき止め湖「草嶺潭」ができ、決壊しては消えた"},{"k":"record","zh":"九二一地震讓草嶺崩出新的堰塞湖，一度是臺灣最大的天然湖泊","en":"The 1999 quake created a new landslide lake at Caoling, briefly Taiwan's largest natural lake.","ja":"1999年の921地震で草嶺に新たなせき止め湖ができ、一時台湾最大の天然湖となった"},{"k":"record","zh":"北港武德宮是臺灣最大、最早的五路財神廟","en":"Beigang's Wude Temple is Taiwan's largest and oldest temple to the Five Gods of Wealth.","ja":"北港の武徳宮は、台湾最大かつ最古の五路財神の廟"},{"k":"record","zh":"1979年虎尾與青森縣大間町結盟，是臺日第一對姊妹市鎮","en":"In 1979 Huwei paired with Ōma in Aomori, the first sister-town tie between Taiwan and Japan.","ja":"1979年、虎尾は青森県大間町と提携し、台日初の姉妹都市となった"},{"k":"record","zh":"西螺果菜市場是臺灣規模最大的蔬果集散中心","en":"Xiluo's fruit and vegetable market is Taiwan's largest produce distribution center.","ja":"西螺の青果市場は、台湾最大規模の青果の集散地"},{"k":"people","zh":"抗日「三猛」之一的柯鐵，在古坑大坪頂建立「鐵國山」基地","en":"Ke Tie, one of the 'Three Fierce' anti-Japanese fighters, set up his Tieguo Mountain base in Gukeng.","ja":"抗日「三猛」の一人・柯鉄は、古坑の大坪頂に拠点「鉄国山」を築いた"},{"k":"origin","zh":"褒忠鄉的名字來自清廷褒獎在林爽文事件中抵抗的義民","en":"Baozhong ('Praise Loyalty') was named by the Qing to honor locals who resisted the 1786 Lin Shuangwen revolt.","ja":"褒忠郷の名は、林爽文事件で抵抗した義民を清朝が褒めたたえたことに由来する"},{"k":"origin","zh":"斗南舊稱「他里霧」，1920年因位在斗六以南而改名","en":"Dounan was once called Dalivoe and was renamed in 1920 for lying south of Douliu.","ja":"斗南の旧称は「他里霧」。1920年、斗六の南にあることから改名した"},{"k":"origin","zh":"北港舊稱「笨港」，1750年河道南移把街市一分為二，南街成了今天鄰縣的新港","en":"Beigang's old port town was split in two when the river shifted in 1750; the southern half became Xingang.","ja":"北港の旧称は「笨港」。1750年に川筋が南へ移って町が二分し、南側は隣県の新港となった"},{"k":"legend","zh":"流傳虎尾地名來自「鄭成功追虎、砍斷虎尾」的故事，其實是虛構的","en":"A tale says Huwei ('tiger tail') is where Koxinga cut off a tiger's tail, but it is considered fiction.","ja":"虎尾の地名は鄭成功が虎の尾を切った話に由来するとされるが、実は創作された伝説"},{"k":"festival","zh":"北港迎媽祖的真人藝閣全國僅存，和炸寒單、鹽水蜂炮並稱「臺灣三大炮」","en":"Beigang's Mazu parade features living-tableau floats and is one of Taiwan's 'three great firecracker festivals'.","ja":"北港の媽祖祭りは人が乗る芸閣が名物で、炸寒単・塩水蜂炮と並ぶ「台湾三大炮」"},{"k":"festival","zh":"中元普渡有「北基隆、南虎尾」的俗語","en":"A saying pairs 'Keelung in the north, Huwei in the south' for Ghost Festival celebrations.","ja":"中元節の盛大さについて「北の基隆、南の虎尾」という言い回しがある"},{"k":"festival","zh":"馬鳴山鎮安宮的五年千歲每五年在元宵節出巡，繞境五股十四莊","en":"Every five years at Lantern Festival, Mamingshan's Zhen'an Temple parades its gods through 14 villages.","ja":"馬鳴山鎮安宮の五年千歳は、5年に一度の元宵節に14の村を巡行する"},{"k":"history","zh":"虎尾1936年設飛行基地，二戰末期曾作為神風特攻隊基地","en":"Huwei's airbase, built in 1936, served as a kamikaze base late in World War II.","ja":"1936年に設けられた虎尾の飛行場は、大戦末期に神風特攻隊の基地となった"},{"k":"history","zh":"清代俗諺「一府二鹿三艋舺四笨港」，笨港指的就是北港一帶","en":"A Qing saying ranked Bengang, today's Beigang area, fourth among Taiwan's great towns.","ja":"清代の俗諺「一府二鹿三艋舺四笨港」の笨港は、北港一帯を指す"},{"k":"history","zh":"北港圓環中央立有顏思齊開拓臺灣登陸紀念碑","en":"A monument to Yan Siqi's landing to settle Taiwan stands in the middle of Beigang's roundabout.","ja":"北港のロータリー中央には、顔思斉の台湾開拓上陸記念碑が立つ"},{"k":"food","zh":"日治時期日本人在古坑荷包山種植約三百公頃咖啡，曾進貢天皇","en":"In Japanese times about 300 ha of Arabica coffee grew on Gukeng's Hebao Mountain, some offered to the emperor.","ja":"日本統治時代、古坑の荷包山に約300ヘクタールのコーヒーが植えられ、天皇に献上された"}]};
